CREATE INDEX IF NOT EXISTS plan_extras_plan_idx ON lektionskollen.plan_extras USING btree (plan_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS ratings_one_per_session ON lektionskollen.ratings USING btree (plan_id, rater_session) WHERE (rater_session IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS plan_uses_teacher_token ON lektionskollen.plan_uses USING btree (teacher_token);
CREATE INDEX IF NOT EXISTS plans_school_id_subject_year_group_idx ON lektionskollen.plans USING btree (school_id, subject, year_group);
