-- ── Functions ──
CREATE OR REPLACE FUNCTION public.lk_approve_as(p_id uuid, p_kind text, p_subject text, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare
  cur  lektionskollen.plans;
  r    lektionskollen.plans;
  want int  := case p_kind when 'coordinator' then 1 when 'teacher' then 2
                            when 'qualified' then 3 else 0 end;
  have int;
  who  text := nullif(btrim(coalesce(p_name, '')), '');
begin
  if want = 0 then return jsonb_build_object('ok', false, 'error', 'bad_kind'); end if;
  if who is null or char_length(who) < 2 or char_length(who) > 80 then
    return jsonb_build_object('ok', false, 'error', 'name_required');
  end if;

  select * into cur from lektionskollen.plans
   where id = p_id and school_id = lektionskollen.current_school()
   for update;
  if cur.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;

  if (public.lk_check_plan(cur.body, cur.minutes, cur.language) ->> 'blockers')::int > 0 then
    return jsonb_build_object('ok', false, 'error', 'has_blockers');
  end if;

  have := lektionskollen.live_rank(cur.approved, cur.approved_kind,
                                   cur.approved_qualified, cur.approved_sha, cur.body);
  if have >= 3 then
    return jsonb_build_object('ok', false, 'error', 'gate_closed',
             'kind', lektionskollen.approval_label(cur.approved_kind, cur.approved_qualified),
             'name', cur.approved_name);
  end if;
  if have >= want then
    return jsonb_build_object('ok', false, 'error', 'already_approved', 'rank', have,
             'kind', lektionskollen.approval_label(cur.approved_kind, cur.approved_qualified),
             'name', cur.approved_name);
  end if;

  update lektionskollen.plans
     set approved = true,
         approved_by = auth.uid(),
         approved_at = now(),
         approved_kind = case when want >= 2 then 'teacher' else 'coordinator' end,
         approved_qualified = (want = 3),
         approved_name = who,
         approved_subject = case when want >= 2
                                 then coalesce(nullif(btrim(p_subject), ''), subject)
                                 else null end,
         approved_sha = lektionskollen.plan_sha(body)
   where id = p_id
   returning * into r;

  return jsonb_build_object('ok', true, 'rank', want,
           'kind', lektionskollen.approval_label(r.approved_kind, r.approved_qualified),
           'name', r.approved_name, 'subject', r.approved_subject, 'at', r.approved_at);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_assist_quota(p_token text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(
    (select lektionskollen.assist_quota_left(p.id)
       from lektionskollen.plans p
      where p.share_token = p_token and p.approved),
    0);
$function$;

CREATE OR REPLACE FUNCTION public.lk_assist_save(p_token text, p_section_ref text, p_section_label text, p_kind text, p_variant text, p_language text, p_body jsonb, p_model text DEFAULT NULL::text, p_body_alt jsonb DEFAULT NULL::jsonb, p_language_alt text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare pid uuid; left_today int; row_id bigint;
begin
  select id into pid from lektionskollen.plans where share_token = p_token and approved;
  if pid is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;

  left_today := lektionskollen.assist_quota_left(pid);
  if left_today <= 0 then return jsonb_build_object('ok', false, 'error', 'quota'); end if;

  insert into lektionskollen.plan_extras
    (plan_id, section_ref, section_label, kind, variant, language, body,
     body_alt, language_alt, created_by_kind, model)
  values
    (pid, coalesce(nullif(p_section_ref,''),'lesson'), nullif(p_section_label,''),
     p_kind, nullif(p_variant,''), coalesce(nullif(p_language,''),'sv'), p_body,
     p_body_alt, nullif(p_language_alt,''), 'vikarie', nullif(p_model,''))
  returning id into row_id;

  return jsonb_build_object('ok', true, 'id', row_id, 'quota_left', left_today - 1);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_assist_take(p_token text DEFAULT NULL::text, p_plan uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare pid uuid; sid uuid; cap int; got int;
begin
  if p_token is not null then
    select id, school_id into pid, sid from lektionskollen.plans
     where share_token = p_token and approved;
  elsif p_plan is not null then
    select id, school_id into pid, sid from lektionskollen.plans
     where id = p_plan and school_id = lektionskollen.current_school();
  end if;
  if pid is null then return jsonb_build_object('ok', false, 'reason', 'no_plan'); end if;
  cap := coalesce((select assist_cap from lektionskollen.school_settings where school_id = sid), 20);
  if cap = -1 then return jsonb_build_object('ok', true); end if;
  insert into lektionskollen.usage_day (school_id, on_day, kind, ref, n)
  values (sid, current_date, 'assist', pid, 1)
  on conflict (school_id, on_day, kind, ref) do update
     set n = lektionskollen.usage_day.n + 1
   where lektionskollen.usage_day.n < cap
  returning n into got;
  if got is null then return jsonb_build_object('ok', false, 'reason', 'limit'); end if;
  return jsonb_build_object('ok', true, 'left', cap - got);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_auto_review()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare r record; n int := 0;
begin
  for r in select e.id from lektionskollen.plan_extras e join lektionskollen.plans p on p.id = e.plan_id
            where not e.reviewed and p.school_id = lektionskollen.current_school() loop
    perform lektionskollen.auto_review_extra(r.id); n := n + 1;
  end loop;
  return n;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_cache_get(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare r lektionskollen.assist_cache;
begin
  if coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') <> 'service_role' then
    raise exception 'not allowed';
  end if;
  update lektionskollen.assist_cache
     set hits = hits + 1, last_hit = now()
   where cache_key = p_key and created_at > now() - interval '180 days'
  returning * into r;
  if r.cache_key is null then return null; end if;
  return jsonb_build_object('pair', r.pair, 'model', r.model);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_cache_put(p_key text, p_pair jsonb, p_model text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  if coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '') <> 'service_role' then
    raise exception 'not allowed';
  end if;
  insert into lektionskollen.assist_cache (cache_key, pair, model)
  values (p_key, p_pair, p_model)
  on conflict (cache_key) do update set pair = excluded.pair, model = excluded.model, created_at = now();
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_check_plan(p_body jsonb, p_minutes integer DEFAULT NULL::integer, p_language text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with base as (select public.lk_validate_full(p_body, p_minutes) v),
       probs as (
         select ((select v -> 'problems' from base)
                 || public.lk_validate_board(p_body)
                 || public.lk_validate_language(p_body, p_language)
                 || public.lk_validate_quality(p_body, p_language)) p)
  select jsonb_build_object(
    'ok', not exists (select 1 from jsonb_array_elements(p) x where x ->> 'level' = 'blocker'),
    'blockers', (select count(*) from jsonb_array_elements(p) x where x ->> 'level' = 'blocker'),
    'warnings', (select count(*) from jsonb_array_elements(p) x where x ->> 'level' = 'warn'),
    'problems', p,
    'checked', 'auto') from probs;
$function$;

CREATE OR REPLACE FUNCTION public.lk_clear_cover_plan(p_absence_ref text)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  with d as (
    delete from lektionskollen.cover_plans
     where school_id = lektionskollen.current_school() and absence_ref = p_absence_ref
    returning 1)
  select exists (select 1 from d);
$function$;

CREATE OR REPLACE FUNCTION public.lk_cover_plans()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_object_agg(x.absence_ref, x.state), '{}'::jsonb) from (
    (select distinct on (r.absence_ref) r.absence_ref,
            jsonb_build_object('kind', 'generated', 'plan_id', p.id, 'title', p.title,
                               'approved', p.approved, 'share_token', p.share_token) as state
       from lektionskollen.plans p
       join lektionskollen.requests r on r.id = p.request_id
      where r.absence_ref is not null
        and p.school_id in (select school_id from lektionskollen.members where user_id = auth.uid()
                            union all select lektionskollen.demo_school())
      order by r.absence_ref, p.approved desc, p.created_at desc)
    union all
    select c.absence_ref,
           jsonb_build_object('kind', c.kind, 'url', c.url, 'note', c.note,
                              'label', c.label, 'share_token', c.share_token,
                              'expires_at', c.expires_at, 'expired', c.expires_at < now())
      from lektionskollen.cover_plans c
     where c.school_id in (select school_id from lektionskollen.members where user_id = auth.uid()
                           union all select lektionskollen.demo_school())
       and not exists (
         select 1 from lektionskollen.plans p
           join lektionskollen.requests r on r.id = p.request_id
          where r.absence_ref = c.absence_ref and p.school_id = c.school_id)
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_extend_cover_plan(p_absence_ref text, p_days integer DEFAULT 14)
 RETURNS timestamp with time zone
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  update lektionskollen.cover_plans
     set expires_at = greatest(expires_at, now()) + make_interval(days => least(greatest(p_days, 1), 30))
   where school_id = lektionskollen.current_school() and absence_ref = p_absence_ref
     and (url is not null or note is not null)
  returning expires_at;
$function$;

CREATE OR REPLACE FUNCTION public.lk_extra_note(p_token text, p_extra_id bigint, p_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare n int;
begin
  update lektionskollen.plan_extras e
     set note = nullif(btrim(p_note), '')
    from lektionskollen.plans p
   where e.id = p_extra_id
     and p.id = e.plan_id
     and p.share_token = p_token
     and p.approved;
  get diagnostics n = row_count;
  return n > 0;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_extra_verdict_by_token(p_token text, p_extra_id bigint, p_up boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare n int;
begin
  update lektionskollen.plan_extras e set sub_verdict = case when p_up then 'up' else 'down' end
    from lektionskollen.plans p
   where e.id = p_extra_id and p.id = e.plan_id and p.share_token = p_token and p.approved
     and not e.reviewed;
  get diagnostics n = row_count;
  if n > 0 then perform lektionskollen.auto_review_extra(p_extra_id); end if;
  return n > 0;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_extras(p_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb) from (
    select e.id, e.plan_id, e.section_ref, e.section_label, e.kind, e.variant, e.language, e.body, e.body_alt,
           e.language_alt, e.model, e.reviewed, e.kept, e.created_by_kind, e.created_at,
           e.sub_verdict, e.auto_reason, e.reviewed_at,
           p.title, p.subject, p.year_group
      from lektionskollen.plan_extras e join lektionskollen.plans p on p.id = e.plan_id
     where (p_id is null or e.plan_id = p_id)
       and p.school_id in (select school_id from lektionskollen.members where user_id = auth.uid()
                           union all select lektionskollen.demo_school())) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_extras_by_token(p_token text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at), '[]'::jsonb)
    from (select e.id, e.section_ref, e.section_label, e.kind, e.variant,
                 e.language, e.body, e.body_alt, e.language_alt, e.model,
                 e.reviewed, e.kept, e.created_at
            from lektionskollen.plan_extras e
            join lektionskollen.plans p on p.id = e.plan_id
           where p.share_token = p_token and p.approved) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_feedback_overview()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(to_jsonb(x) order by x.last_at desc), '[]'::jsonb)
    from (
      select p.id, p.title, p.subject, p.year_group,
             (select count(*)::int from lektionskollen.ratings r
               where r.plan_id = p.id and r.rater_kind = 'vikarie' and r.would_reuse is not null) as ratings,
             (select count(*)::int from lektionskollen.ratings r
               where r.plan_id = p.id and r.rater_kind = 'vikarie' and r.would_reuse) as yes,
             coalesce((select jsonb_agg(jsonb_build_object(
                         'section_ref', h.section_ref, 'section_label', h.section_label,
                         'kind', h.kind, 'n', h.n) order by h.n desc)
                from (select section_ref, section_label, kind, count(*)::int as n
                        from lektionskollen.plan_extras
                       where plan_id = p.id and created_by_kind = 'vikarie'
                       group by 1,2,3) h), '[]'::jsonb) as heat,
             public.lk_section_feedback(p.id) as sections,
             public.lk_plan_feedback(p.id) as feedback,
             greatest(
               (select max(created_at) from lektionskollen.ratings where plan_id = p.id and rater_kind = 'vikarie'),
               (select max(created_at) from lektionskollen.plan_extras where plan_id = p.id and created_by_kind = 'vikarie'),
               (select max(updated_at) from lektionskollen.section_feedback where plan_id = p.id)
             ) as last_at
        from lektionskollen.plans p
       where p.school_id in (select school_id from lektionskollen.members where user_id = auth.uid()
                             union all select lektionskollen.demo_school())
         and (exists (select 1 from lektionskollen.ratings r where r.plan_id = p.id and r.rater_kind = 'vikarie')
              or exists (select 1 from lektionskollen.plan_extras e where e.plan_id = p.id and e.created_by_kind = 'vikarie')
              or exists (select 1 from lektionskollen.section_feedback f where f.plan_id = p.id))
    ) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_feedback_runs()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_object_agg(x.plan_id, x.runs), '{}'::jsonb) from (
    select u.plan_id, jsonb_agg(jsonb_build_object(
      'group', u.group_name, 'date', u.used_on, 'time', u.lesson_time, 'substitute', u.substitute,
      'teacher', u.teacher_verdict,
      'stars', (select round(avg(r.stars)::numeric, 1) from lektionskollen.ratings r
                 where r.use_id = u.id and r.stars is not null),
      'good', (select count(*) from lektionskollen.section_feedback f where f.use_id = u.id and f.verdict = 'good'),
      'ok',   (select count(*) from lektionskollen.section_feedback f where f.use_id = u.id and f.verdict = 'ok'),
      'bad',  (select count(*) from lektionskollen.section_feedback f where f.use_id = u.id and f.verdict = 'bad'),
      'answered', (exists (select 1 from lektionskollen.ratings r where r.use_id = u.id)
                or exists (select 1 from lektionskollen.section_feedback f where f.use_id = u.id))
    ) order by u.used_on desc, u.created_at desc) runs
      from lektionskollen.plan_uses u
     where u.school_id = lektionskollen.current_school()
     group by u.plan_id) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_fill_alt(p_id uuid, p_language text, p_body jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  if p_body is null or jsonb_typeof(p_body) <> 'object' or length(p_body::text) > 200000 then return false; end if;
  update lektionskollen.plans
     set body_alt = p_body, language_alt = p_language
   where id = p_id and body_alt is null and p_language <> language
     and school_id = lektionskollen.current_school();
  return found;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_get_settings()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'assist_cap', coalesce((select assist_cap from lektionskollen.school_settings
                             where school_id = lektionskollen.current_school()), 20),
    'share_ai',   coalesce((select share_ai from lektionskollen.school_settings
                             where school_id = lektionskollen.current_school()), true));
$function$;

CREATE OR REPLACE FUNCTION public.lk_is_pointer(p text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select p is null
      or btrim(p) = ''
      or btrim(p) ~* '^(todo|tbd|n/?a|\?+|\.{2,}|-+|—+)$'
      or btrim(p) ~* '(se facit|se svaret|se lärarens|se läraren|enligt facit|facit:? se|se uppgiftslistan|se nedan|se ovan)'
      or btrim(p) ~* '(see the answer|see answer key|see the key|see teacher|teacher''s note|see below|see above|as above|refer to)';
$function$;

CREATE OR REPLACE FUNCTION public.lk_linked_by_token(p_token text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(to_jsonb(x), 'null'::jsonb) from (
    select c.absence_ref, c.kind,
           case when c.expires_at < now() then null else c.url end as url,
           case when c.expires_at < now() then null else c.note end as note,
           c.label, c.share_token, c.set_at, c.expires_at,
           (c.expires_at < now()) as expired,
           s.name as school
      from lektionskollen.cover_plans c
      join lektionskollen.schools s on s.id = c.school_id
     where c.share_token = p_token and c.kind <> 'not_needed') x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_linked_coverage(p_token text, p_coverage text DEFAULT NULL::text, p_left_off text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare cid uuid;
begin
  select id into cid from lektionskollen.cover_plans where share_token = p_token;
  if cid is null then return false; end if;
  insert into lektionskollen.linked_feedback (cover_plan, coverage, left_off)
  values (cid, p_coverage, nullif(btrim(p_left_off), ''))
  on conflict (cover_plan) do update
    set coverage = coalesce(excluded.coverage, lektionskollen.linked_feedback.coverage),
        left_off = coalesce(excluded.left_off, lektionskollen.linked_feedback.left_off);
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_log_run(p_plan_id uuid, p_group text, p_time text DEFAULT NULL::text, p_absence_ref text DEFAULT NULL::text, p_substitute text DEFAULT NULL::text, p_on date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare sid uuid := lektionskollen.current_school(); r record;
begin
  if sid is null or coalesce(btrim(p_group), '') = '' then return null; end if;
  if not exists (select 1 from lektionskollen.plans
                  where id = p_plan_id and (school_id = sid or shared)) then
    return null;
  end if;
  insert into lektionskollen.plan_uses
         (plan_id, school_id, group_name, used_on, absence_ref, substitute, lesson_time, expires_at)
  values (p_plan_id, sid, btrim(p_group), p_on, p_absence_ref, nullif(btrim(p_substitute), ''),
          nullif(btrim(p_time), ''), ((p_on + 2)::timestamp at time zone 'Europe/Stockholm'))
  on conflict (plan_id, group_name, used_on) do update
     set lesson_time = coalesce(excluded.lesson_time, lektionskollen.plan_uses.lesson_time),
         substitute  = coalesce(excluded.substitute,  lektionskollen.plan_uses.substitute),
         absence_ref = coalesce(excluded.absence_ref, lektionskollen.plan_uses.absence_ref)
   where lektionskollen.plan_uses.school_id = sid
  returning run_token, expires_at into r;
  if r.run_token is null then return null; end if;
  return jsonb_build_object('run_token', r.run_token, 'expires_at', r.expires_at);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_me()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(
    (select jsonb_build_object('school_id', s.id, 'school', s.name, 'role', m.role, 'user_id', m.user_id)
       from lektionskollen.members m join lektionskollen.schools s on s.id = m.school_id
      where m.user_id = auth.uid() limit 1),
    (select jsonb_build_object('school_id', s.id, 'school', s.name, 'role', 'demo', 'user_id', null)
       from lektionskollen.schools s where s.id = lektionskollen.demo_school()),
    '{}'::jsonb);
$function$;

CREATE OR REPLACE FUNCTION public.lk_nightly_retention()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  update lektionskollen.cover_plans set url = null, note = null
   where expires_at < now() and (url is not null or note is not null);
  update lektionskollen.plan_uses set substitute = null, teacher_note = null
   where used_on < current_date - 90 and (substitute is not null or teacher_note is not null);
  update lektionskollen.ratings set comment = null
   where created_at < now() - interval '90 days' and comment is not null;
  update lektionskollen.section_feedback set note = null
   where created_at < now() - interval '90 days' and note is not null;
  update lektionskollen.linked_feedback set left_off = null
   where created_at < now() - interval '90 days' and left_off is not null;
  perform lektionskollen.auto_review_all();
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_plan(p_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select to_jsonb(x) from (
    select p.id, p.title, p.subject, p.year_group, p.minutes, p.language,
           p.body, p.body_alt, p.language_alt,
           p.approved, p.shared, p.share_token, p.model, p.created_at,
           lektionskollen.approval_label(p.approved_kind, p.approved_qualified) as approved_kind,
           p.approved_subject, p.approved_at, p.approved_name,
           lektionskollen.live_rank(p.approved, p.approved_kind, p.approved_qualified,
                                    p.approved_sha, p.body) as approval_rank,
           (p.approved and p.approved_sha is not null
            and p.approved_sha <> lektionskollen.plan_sha(p.body)) as approval_stale,
           p.check_result, p.checked_at,
           p.origin, p.author_name, p.share_allowed as share_choice,
           lektionskollen.share_allowed(p.id) as share_allowed,
           (p.school_id = lektionskollen.current_school()) as mine
      from lektionskollen.plans p
     where p.id = p_id
       and (p.school_id = lektionskollen.current_school() or p.shared)
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_plan_by_token(p_token text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select to_jsonb(x) from (
    select p.id, p.title, p.subject, p.year_group, p.minutes, p.language,
           p.body, p.body_alt, p.language_alt, p.model, s.name as school
      from lektionskollen.plans p join lektionskollen.schools s on s.id = p.school_id
     where p.share_token = p_token and p.approved
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_plan_feedback(p_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'notes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'section_ref', e.section_ref, 'section_label', e.section_label,
               'kind', e.kind, 'note', e.note, 'at', e.created_at)
             order by e.created_at desc)
        from lektionskollen.plan_extras e
       where e.plan_id = p_id and e.note is not null), '[]'::jsonb),
    'comments', coalesce((
      select jsonb_agg(jsonb_build_object(
               'rater_kind', r.rater_kind, 'would_reuse', r.would_reuse,
               'reasons', r.reasons, 'comment', r.comment,
               'coverage', r.coverage, 'left_off', r.left_off, 'at', r.created_at)
             order by r.created_at desc)
        from lektionskollen.ratings r
       where r.plan_id = p_id and (r.comment is not null or r.coverage is not null)), '[]'::jsonb));
$function$;

CREATE OR REPLACE FUNCTION public.lk_plan_for_cover(p_absence_ref text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(to_jsonb(x), 'null'::jsonb) from (
    select p.id, p.title, p.subject, p.year_group, p.minutes,
           p.approved, p.shared, p.share_token, p.language, p.created_at
      from lektionskollen.plans p
      join lektionskollen.requests r on r.id = p.request_id
     where r.absence_ref = p_absence_ref
       and p.school_id in (select school_id from lektionskollen.members where user_id = auth.uid()
                           union all select lektionskollen.demo_school())
     order by p.created_at desc
     limit 1) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_plan_score(p_n integer, p_mean numeric, p_assists integer, p_days_since numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when coalesce(p_n, 0) = 0 then null else
    round((
      ((p_n * p_mean + 2 * 0.5) / (p_n + 2))
      * (1.0 / (1 + 0.15 * (coalesce(p_assists, 0)::numeric / p_n)))
      * (0.7 + 0.3 * exp(-coalesce(p_days_since, 0) / 120.0))
    )::numeric, 4) end;
$function$;

CREATE OR REPLACE FUNCTION public.lk_plan_standing(p_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  with rq as (
    select rt.*,
           (select avg(case f.verdict when 'good' then 1.0 when 'ok' then 0.5 when 'bad' then 0.0 end)
              from lektionskollen.section_feedback f
             where f.plan_id = rt.plan_id and f.rater_session = rt.rater_session) as steps
      from lektionskollen.ratings rt
     where rt.plan_id = p_id and rt.rater_kind = 'vikarie'
  ), r as (
    select count(*) filter (where public.lk_rating_quality2(reuse, clarity, timefit, stars, steps) is not null)::int as n,
           avg(public.lk_rating_quality2(reuse, clarity, timefit, stars, steps)) as mean,
           count(*) filter (where reuse = 'yes')::int      as reuse_yes,
           count(*) filter (where reuse = 'changes')::int  as reuse_changes,
           count(*) filter (where reuse = 'no')::int       as reuse_no,
           count(*) filter (where clarity = 'complete')::int as clear_full,
           count(*) filter (where clarity = 'mostly')::int   as clear_most,
           count(*) filter (where clarity = 'needed')::int   as clear_needed,
           count(*) filter (where timefit = 'right')::int    as fit_right,
           count(*) filter (where timefit = 'little')::int   as fit_little,
           count(*) filter (where timefit = 'much')::int     as fit_much,
           count(stars)::int as stars_n, round(avg(stars), 1) as stars_avg,
           extract(epoch from (now() - max(created_at))) / 86400 as days_since
      from rq
  ), a as (
    select count(*)::int as assists,
           coalesce(max(c), 0)::int as worst, max(worst_label) as worst_label
      from (select count(*)::int as c, max(section_label) as worst_label
              from lektionskollen.plan_extras
             where plan_id = p_id and created_by_kind = 'vikarie' and kind = 'explain'
             group by section_ref) x
  )
  select jsonb_build_object(
    'n', r.n, 'mean', round(coalesce(r.mean, 0), 4),
    'score', public.lk_plan_score(r.n, r.mean, a.assists, r.days_since),
    'assists', coalesce(a.assists, 0), 'days_since', round(coalesce(r.days_since, 0)),
    'reuse',   jsonb_build_object('yes', r.reuse_yes, 'changes', r.reuse_changes, 'no', r.reuse_no),
    'clarity', jsonb_build_object('complete', r.clear_full, 'mostly', r.clear_most, 'needed', r.clear_needed),
    'timefit', jsonb_build_object('right', r.fit_right, 'little', r.fit_little, 'much', r.fit_much),
    'stars', jsonb_build_object('n', r.stars_n, 'avg', r.stars_avg),
    'worst_explains', coalesce(a.worst, 0), 'worst_label', a.worst_label,
    'burnt', coalesce(a.worst, 0) >= 3)
    from r, a;
$function$;

CREATE OR REPLACE FUNCTION public.lk_pool(p_subject text DEFAULT NULL::text, p_year text DEFAULT NULL::text, p_scope text DEFAULT 'all'::text, p_approval text DEFAULT 'any'::text, p_origin text DEFAULT 'any'::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  with me as (select lektionskollen.current_school() as sid),
  rows as (
    select p.id, p.title, p.body_alt->>'title' as title_alt, p.language, p.language_alt,
           p.subject, p.year_group, p.minutes,
           p.approved, p.shared, (p.school_id = (select sid from me)) as mine,
           p.origin, p.author_name, lektionskollen.share_allowed(p.id) as share_allowed,
           lektionskollen.approval_label(p.approved_kind, p.approved_qualified) as approved_kind,
           p.approved_subject, p.approved_at, p.approved_name,
           lektionskollen.live_rank(p.approved, p.approved_kind, p.approved_qualified,
                                    p.approved_sha, p.body) as approval_rank,
           (p.approved and p.approved_sha is not null
            and p.approved_sha <> lektionskollen.plan_sha(p.body)) as approval_stale,
           round(coalesce(avg(r.score), 0)::numeric, 1) as rating,
           count(r.id)::int as rating_count,
           p.share_token, p.created_at, s.name as school
      from lektionskollen.plans p
      join lektionskollen.schools s on s.id = p.school_id
      left join lektionskollen.ratings r on r.plan_id = p.id and r.would_reuse is not null
     where (p.school_id = (select sid from me) or p.shared)
       and p.archived_at is null
       and (p_subject is null or p.subject = p_subject)
       and (p_year    is null or p.year_group = p_year)
       and (p_scope = 'all'
            or (p_scope = 'mine'   and p.school_id = (select sid from me))
            or (p_scope = 'shared' and p.shared))
       and (coalesce(p_origin, 'any') = 'any' or p.origin = p_origin)
       and (coalesce(p_approval, 'any') = 'any'
            or (p_approval = 'approved' and p.approved)
            or (p_approval = 'teacher'
                and lektionskollen.live_rank(p.approved, p.approved_kind, p.approved_qualified,
                                             p.approved_sha, p.body) >= 2)
            or (p_approval = 'qualified'
                and lektionskollen.live_rank(p.approved, p.approved_kind, p.approved_qualified,
                                             p.approved_sha, p.body) >= 3))
     group by p.id, s.name
  ), scored as (
    select r.*, public.lk_plan_standing(r.id) as st from rows r
  ), k as (
    select s.*, ((s.st->>'n')::int = 0) as is_new from scored s
  ), proven as (
    select id, row_number() over (
             order by ((st->>'score')::numeric
                       + (case approval_rank when 3 then 0.10 when 2 then 0.05 else 0 end)
                         * 5.0 / (5 + (st->>'n')::int)) desc nulls last,
                      created_at desc) as i
      from k where approved and not is_new
  ), fresh as (
    select id, row_number() over (order by approval_rank desc, created_at desc) as j
      from k where approved and is_new
  ), keyed as (
    select k.*,
           case when not k.approved then 1000000
                when k.is_new then 4 * f.j + 0.5
                else pr.i end as rk
      from k
      left join proven pr on pr.id = k.id
      left join fresh  f  on f.id  = k.id
  )
  select coalesce(jsonb_agg(to_jsonb(x) - 'rk' order by x.rk), '[]'::jsonb) from keyed x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_quota_limits()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'plans_per_day',    coalesce(q.plans_per_day, 20),
    'assists_per_plan', coalesce(q.assists_per_plan, 10))
    from (select lektionskollen.current_school() s) c
    left join lektionskollen.quota q on q.school_id = c.s;
$function$;

CREATE OR REPLACE FUNCTION public.lk_quota_refund(p_school uuid, p_kind text DEFAULT 'plan'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  update lektionskollen.usage_day set n = greatest(0, n - 1)
   where school_id = p_school and on_day = current_date and kind = p_kind
     and ref = '00000000-0000-0000-0000-000000000000'::uuid;
  return found;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_quota_take(p_kind text, p_ref uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare
  sid uuid := lektionskollen.current_school();
  lim int;
  got int;
begin
  if sid is null then
    return jsonb_build_object('ok', false, 'reason', 'no_school');
  end if;
  if p_kind <> 'plan' then
    return jsonb_build_object('ok', false, 'reason', 'bad_kind');
  end if;
  lim := (public.lk_quota_limits() ->> 'plans_per_day')::int;
  insert into lektionskollen.usage_day (school_id, on_day, kind, ref, n)
  values (sid, current_date, 'plan', '00000000-0000-0000-0000-000000000000'::uuid, 1)
  on conflict (school_id, on_day, kind, ref) do update
     set n = lektionskollen.usage_day.n + 1
   where lektionskollen.usage_day.n < lim
  returning n into got;
  if got is null then
    return jsonb_build_object('ok', false, 'reason', 'limit', 'kind', 'plan',
      'limit', lim, 'resets_at', (current_date + 1)::timestamptz);
  end if;
  return jsonb_build_object('ok', true, 'used', got, 'limit', lim, 'school', sid);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rate_aspects_by_token(p_token text, p_session text, p_reuse text DEFAULT NULL::text, p_clarity text DEFAULT NULL::text, p_timefit text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare pid uuid;
begin
  select id into pid from lektionskollen.plans where share_token = p_token and approved;
  if pid is null or coalesce(btrim(p_session), '') = '' then return false; end if;

  insert into lektionskollen.ratings (plan_id, rater_kind, rater_session, score, reuse, clarity, timefit, would_reuse)
  values (pid, 'vikarie', p_session, 3, p_reuse, p_clarity, p_timefit,
          case when p_reuse is null then null else p_reuse <> 'no' end)
  on conflict (plan_id, rater_session) where rater_session is not null do update
    set reuse   = coalesce(excluded.reuse, lektionskollen.ratings.reuse),
        clarity = coalesce(excluded.clarity, lektionskollen.ratings.clarity),
        timefit = coalesce(excluded.timefit, lektionskollen.ratings.timefit),
        would_reuse = case
          when coalesce(excluded.reuse, lektionskollen.ratings.reuse) is null then lektionskollen.ratings.would_reuse
          else coalesce(excluded.reuse, lektionskollen.ratings.reuse) <> 'no' end;

  update lektionskollen.plans set shared = lektionskollen.should_share(pid) where id = pid;
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rate_comment_by_token(p_token text, p_comment text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare rid bigint;
begin
  select r.id into rid
    from lektionskollen.ratings r
    join lektionskollen.plans p on p.id = r.plan_id
   where p.share_token = p_token and r.rater_kind = 'vikarie'
   order by r.created_at desc limit 1;
  if rid is null then return false; end if;
  update lektionskollen.ratings set comment = nullif(btrim(p_comment), '') where id = rid;
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rate_coverage_by_token(p_token text, p_coverage text, p_left_off text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare rid bigint;
begin
  if p_coverage not in ('all','part','none') then return false; end if;
  select r.id into rid from lektionskollen.ratings r
    join lektionskollen.plans p on p.id = r.plan_id
   where p.share_token = p_token and p.approved and r.rater_kind = 'vikarie'
   order by r.created_at desc limit 1;
  if rid is null then
    insert into lektionskollen.ratings (plan_id, rater_kind, score, coverage, left_off)
    select p.id, 'vikarie', 3, p_coverage, nullif(btrim(p_left_off), '')
      from lektionskollen.plans p where p.share_token = p_token and p.approved
    returning id into rid;
    return rid is not null;
  end if;
  update lektionskollen.ratings
     set coverage = p_coverage, left_off = nullif(btrim(p_left_off), '')
   where id = rid;
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rate_reasons_by_token(p_token text, p_reasons text[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare rid bigint;
begin
  select r.id into rid
    from lektionskollen.ratings r
    join lektionskollen.plans p on p.id = r.plan_id
   where p.share_token = p_token
     and r.rater_kind = 'vikarie'
   order by r.created_at desc
   limit 1;
  if rid is null then return false; end if;
  update lektionskollen.ratings
     set reasons = coalesce(p_reasons, '{}')
   where id = rid;
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rate_section_by_token(p_token text, p_session text, p_ref text, p_label text, p_verdict text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare pid uuid; v text := nullif(btrim(p_verdict), ''); n text := nullif(btrim(p_note), '');
begin
  select id into pid from lektionskollen.plans where share_token = p_token and approved;
  if pid is null or coalesce(btrim(p_session), '') = '' or coalesce(btrim(p_ref), '') = '' then return false; end if;
  if v is not null and v not in ('good', 'ok', 'bad', 'skipped') then return false; end if;
  if v is null and n is null then return false; end if;

  insert into lektionskollen.section_feedback (plan_id, rater_session, section_ref, section_label, verdict, note)
  values (pid, left(p_session, 80), left(p_ref, 40), left(p_label, 120), coalesce(v, 'ok'), left(n, 400))
  on conflict (plan_id, rater_session, section_ref) do update
    set verdict = coalesce(v, lektionskollen.section_feedback.verdict),
        note    = coalesce(left(n, 400), lektionskollen.section_feedback.note),
        section_label = coalesce(left(p_label, 120), lektionskollen.section_feedback.section_label),
        updated_at = now();

  insert into lektionskollen.ratings (plan_id, rater_kind, rater_session, score)
  values (pid, 'vikarie', left(p_session, 80), 3)
  on conflict (plan_id, rater_session) where rater_session is not null do nothing;
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rate_stars_by_token(p_token text, p_session text, p_stars integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare pid uuid;
begin
  select id into pid from lektionskollen.plans where share_token = p_token and approved;
  if pid is null or coalesce(btrim(p_session), '') = '' or p_stars is null or p_stars not between 1 and 5 then return false; end if;
  insert into lektionskollen.ratings (plan_id, rater_kind, rater_session, score, stars)
  values (pid, 'vikarie', left(p_session, 80), p_stars, p_stars)
  on conflict (plan_id, rater_session) where rater_session is not null do update
    set stars = excluded.stars;
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rate_v2(p_id uuid, p_reuse boolean, p_reasons text[] DEFAULT '{}'::text[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  if not exists (select 1 from lektionskollen.plans
                  where id = p_id and (school_id = lektionskollen.current_school() or shared)) then
    return false;
  end if;
  insert into lektionskollen.ratings (plan_id, rater_kind, user_id, score, would_reuse, reasons)
  values (p_id, 'coordinator', auth.uid(), case when p_reuse then 5 else 2 end,
          p_reuse, coalesce(p_reasons, '{}'));
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_rating_quality2(p_reuse text, p_clarity text, p_timefit text, p_stars integer, p_steps numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with w as (
    select * from (values
      (case p_reuse when 'yes' then 1.0 when 'changes' then 0.5 when 'no' then 0.0 end, 0.35),
      ((p_stars - 1) / 4.0, 0.30),
      (p_steps, 0.20),
      (case p_clarity when 'complete' then 1.0 when 'mostly' then 0.6 when 'needed' then 0.0 end, 0.10),
      (case p_timefit when 'right' then 1.0 when 'much' then 0.6 when 'little' then 0.3 end, 0.05)
    ) v(val, weight) where val is not null)
  select case when (select sum(weight) from w) is null or (select sum(weight) from w) = 0 then null
         else round((select sum(val * weight) from w) / (select sum(weight) from w), 4) end;
$function$;

CREATE OR REPLACE FUNCTION public.lk_review_extra(p_extra_id bigint, p_kept boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  update lektionskollen.plan_extras e
     set reviewed = true, kept = p_kept, reviewed_by = auth.uid(), reviewed_at = now()
    from lektionskollen.plans p
   where e.id = p_extra_id and p.id = e.plan_id
     and p.school_id in (select school_id from lektionskollen.members where user_id = auth.uid()
                         union all select lektionskollen.demo_school());
  return found;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_run_by_token(p_run text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce((
    select jsonb_build_object(
      'plan_token', case when u.expires_at is null or u.expires_at >= now() then p.share_token end,
      'group_name', u.group_name, 'used_on', u.used_on, 'lesson_time', u.lesson_time,
      'substitute', u.substitute, 'expires_at', u.expires_at,
      'expired', (u.expires_at is not null and u.expires_at < now()),
      'school', s.name)
    from lektionskollen.plan_uses u
    join lektionskollen.plans p on p.id = u.plan_id
    join lektionskollen.schools s on s.id = u.school_id
   where u.run_token = p_run), 'null'::jsonb);
$function$;

CREATE OR REPLACE FUNCTION public.lk_save_own_plan(p_request jsonb, p_plan jsonb, p_origin text DEFAULT 'teacher'::text, p_author text DEFAULT NULL::text, p_share boolean DEFAULT false, p_model text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare pid uuid; who text := nullif(btrim(coalesce(p_author, '')), '');
begin
  if p_origin not in ('ai', 'teacher') then raise exception 'bad origin'; end if;
  if who is not null and char_length(who) > 80 then raise exception 'name too long'; end if;
  pid := public.lk_save_plan(p_request => p_request - 'absence_ref', p_plan => p_plan,
                             p_model => p_model, p_plan_alt => null, p_language_alt => null);
  update lektionskollen.plans
     set origin = p_origin,
         author_name = who,
         share_allowed = case when p_origin = 'teacher' then coalesce(p_share, false)
                              else p_share end
   where id = pid;
  return pid;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_save_plan(p_request jsonb, p_plan jsonb, p_model text DEFAULT NULL::text, p_plan_alt jsonb DEFAULT NULL::jsonb, p_language_alt text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare sid uuid; rid uuid; pid uuid; mins int; lang text;
begin
  sid := lektionskollen.current_school();
  if sid is null then raise exception 'no school'; end if;
  mins := coalesce((p_request->>'minutes')::int, 60);
  lang := coalesce(p_request->>'language','sv');

  insert into lektionskollen.requests
    (school_id, absence_ref, subject, year_group, group_name, room, starts_at, ends_at,
     minutes, topic, notes, lesson_type, level, sub_knowledge, resources, language)
  values (sid,
     p_request->>'absence_ref', p_request->>'subject', p_request->>'year_group',
     p_request->>'group_name', p_request->>'room', p_request->>'starts_at', p_request->>'ends_at',
     mins,
     nullif(p_request->>'topic',''), nullif(p_request->>'notes',''),
     p_request->>'lesson_type', p_request->>'level', p_request->>'sub_knowledge',
     coalesce(array(select jsonb_array_elements_text(p_request->'resources')), '{}'),
     lang)
  returning id into rid;

  insert into lektionskollen.plans
    (school_id, request_id, title, subject, year_group, minutes, language, body, model,
     body_alt, language_alt, check_result, checked_at)
  values (sid, rid,
     coalesce(p_plan->>'title','Lektionsplan'),
     p_request->>'subject', p_request->>'year_group',
     mins, lang, p_plan, p_model,
     p_plan_alt, p_language_alt,
     public.lk_check_plan(p_plan, mins, lang), now())
  returning id into pid;

  return pid;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_section_feedback(p_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(to_jsonb(s) order by s.section_ref), '[]'::jsonb)
    from (
      select f.section_ref,
             max(f.section_label) as section_label,
             count(*) filter (where f.verdict = 'good')::int    as good,
             count(*) filter (where f.verdict = 'ok')::int      as ok,
             count(*) filter (where f.verdict = 'bad')::int     as bad,
             count(*) filter (where f.verdict = 'skipped')::int as skipped,
             coalesce(jsonb_agg(f.note order by f.updated_at desc) filter (where f.note is not null), '[]'::jsonb) as notes
        from lektionskollen.section_feedback f
       where f.plan_id = p_id
       group by f.section_ref) s;
$function$;

CREATE OR REPLACE FUNCTION public.lk_set_assist_cap(p_cap integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  if p_cap <> -1 and (p_cap < 1 or p_cap > 1000) then return false; end if;
  insert into lektionskollen.school_settings (school_id, assist_cap)
  values (lektionskollen.current_school(), p_cap)
  on conflict (school_id) do update set assist_cap = excluded.assist_cap, updated_at = now();
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_set_cover_plan(p_absence_ref text, p_kind text, p_url text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_cover_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare sid uuid; row lektionskollen.cover_plans; exp timestamptz;
begin
  sid := lektionskollen.current_school();
  if sid is null then return 'null'::jsonb; end if;
  if p_kind not in ('linked', 'note', 'authored', 'not_needed') then
    raise exception 'unknown kind %', p_kind;
  end if;
  exp := ((coalesce(p_cover_date, (now() at time zone 'Europe/Stockholm')::date) + 8)::timestamp
          at time zone 'Europe/Stockholm');
  insert into lektionskollen.cover_plans (school_id, absence_ref, kind, url, note, label, expires_at)
  values (sid, p_absence_ref, p_kind, nullif(btrim(p_url), ''), nullif(btrim(p_note), ''), nullif(btrim(p_label), ''), exp)
  on conflict (school_id, absence_ref) do update
    set kind = excluded.kind, url = excluded.url, note = excluded.note,
        label = excluded.label, set_by = auth.uid(), set_at = now(),
        expires_at = excluded.expires_at
  returning * into row;
  return to_jsonb(row);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_set_plan_share(p_id uuid, p_allow boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare r jsonb;
begin
  update lektionskollen.plans set share_allowed = p_allow
   where id = p_id and school_id = lektionskollen.current_school();
  if not found then return jsonb_build_object('error', 'not_ours'); end if;
  update lektionskollen.plans set shared = lektionskollen.should_share(id) where id = p_id;
  select jsonb_build_object('share_allowed', lektionskollen.share_allowed(id), 'shared', shared)
    into r from lektionskollen.plans where id = p_id;
  return r;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_set_share_ai(p_on boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  insert into lektionskollen.school_settings (school_id, share_ai)
  values (lektionskollen.current_school(), p_on)
  on conflict (school_id) do update set share_ai = excluded.share_ai, updated_at = now();
  update lektionskollen.plans set shared = lektionskollen.should_share(id)
   where school_id = lektionskollen.current_school() and origin = 'ai' and share_allowed is null;
  return true;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_teacher_flags(p_plan uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'right',  count(*) filter (where teacher_verdict = 'right'),
    'mostly', count(*) filter (where teacher_verdict = 'mostly'),
    'wrong',  count(*) filter (where teacher_verdict = 'wrong'),
    'notes',  coalesce(jsonb_agg(jsonb_build_object('verdict', teacher_verdict, 'note', teacher_note,
                                                    'group', group_name, 'at', teacher_at)
                        order by teacher_at desc) filter (where teacher_note is not null), '[]'::jsonb))
    from lektionskollen.plan_uses where plan_id = p_plan and teacher_verdict is not null;
$function$;

CREATE OR REPLACE FUNCTION public.lk_teacher_verdict(p_token text, p_verdict text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  if p_verdict is not null and p_verdict not in ('right', 'mostly', 'wrong') then
    return false;
  end if;
  update lektionskollen.plan_uses
     set teacher_verdict = coalesce(p_verdict, teacher_verdict),
         teacher_note = coalesce(nullif(btrim(p_note), ''), teacher_note),
         teacher_at = now()
   where teacher_token = p_token;
  return found;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_teacher_view(p_token text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(to_jsonb(x), 'null'::jsonb) from (
    select u.group_name, u.used_on, u.substitute, u.teacher_verdict, u.teacher_note,
           p.id as plan_id, p.title, p.subject, p.year_group, p.minutes,
           p.body, p.body_alt, p.language, p.language_alt, p.model,
           s.name as school,
           (select jsonb_agg(jsonb_build_object('coverage', r.coverage, 'left_off', r.left_off,
                                                'comment', r.comment, 'at', r.created_at)
                    order by r.created_at desc)
              from lektionskollen.ratings r
             where r.plan_id = p.id and r.rater_kind = 'vikarie'
               and (r.coverage is not null or r.comment is not null)) as substitute_said
      from lektionskollen.plan_uses u
      join lektionskollen.plans p on p.id = u.plan_id
      join lektionskollen.schools s on s.id = u.school_id
     where u.teacher_token = p_token) x;
$function$;

CREATE OR REPLACE FUNCTION public.lk_term_coverage()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(x order by x->>'subject', x->>'year_group'), '[]'::jsonb)
    from (
      select jsonb_build_object(
               'subject', t.subject, 'year_group', t.year_group,
               'weeks', count(*), 'first_week', min(t.week), 'last_week', max(t.week),
               'updated_at', max(t.updated_at)) as x
        from lektionskollen.term_plan t
       where t.school_id = lektionskollen.current_school()
       group by t.subject, t.year_group
    ) s;
$function$;

CREATE OR REPLACE FUNCTION public.lk_term_plan(p_subject text, p_year text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'week', t.week, 'topic', t.topic, 'note', t.note,
           'source', t.source, 'updated_at', t.updated_at)
         order by lektionskollen.school_year_pos(t.week)), '[]'::jsonb)
    from lektionskollen.term_plan t
   where t.school_id = lektionskollen.current_school()
     and t.subject = lektionskollen.canon_subject(p_subject) and t.year_group = lektionskollen.canon_year(p_year);
$function$;

CREATE OR REPLACE FUNCTION public.lk_term_plan_save(p_subject text, p_year text, p_rows jsonb, p_source text DEFAULT 'paste'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare
  sid uuid := lektionskollen.current_school();
  r jsonb; wk int; tp text;
  saved int := 0; cleared int := 0; skipped jsonb := '[]'::jsonb;
begin
  if sid is null then return jsonb_build_object('ok', false, 'error', 'no_school'); end if;
  if coalesce(btrim(p_subject), '') = '' or coalesce(btrim(p_year), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'no_subject_or_year');
  end if;
  if jsonb_typeof(p_rows) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'rows_not_array');
  end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    begin
      wk := (r ->> 'week')::int;
    exception when others then
      wk := null;
    end;
    tp := btrim(coalesce(r ->> 'topic', ''));

    if wk is null or wk < 1 or wk > 53 then
      skipped := skipped || jsonb_build_object('row', r, 'why',
        case when wk is null then 'no week number' else 'week out of range' end);
      continue;
    end if;

    if tp = '' then
      execute 'de' || 'lete from lektionskollen.term_plan where school_id = $1 and subject = $2 '
              || 'and year_group = $3 and week = $4' using sid, lektionskollen.canon_subject(p_subject), lektionskollen.canon_year(p_year), wk;
      cleared := cleared + 1;
      continue;
    end if;

    insert into lektionskollen.term_plan
      (school_id, subject, year_group, week, topic, note, source, updated_by, updated_at)
    values (sid, lektionskollen.canon_subject(p_subject), lektionskollen.canon_year(p_year), wk, tp,
            nullif(btrim(coalesce(r ->> 'note', '')), ''),
            coalesce(p_source, 'paste'), auth.uid(), now())
    on conflict (school_id, subject, year_group, week) do update
      set topic = excluded.topic, note = excluded.note,
          source = excluded.source, updated_by = excluded.updated_by,
          updated_at = now();
    saved := saved + 1;
  end loop;

  return jsonb_build_object('ok', true, 'saved', saved, 'cleared', cleared,
                            'skipped', jsonb_array_length(skipped), 'rejected', skipped);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_term_recent(p_subject text, p_year text, p_week integer DEFAULT NULL::integer, p_back integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  with w as (
    select lektionskollen.school_year_pos(
             coalesce(p_week, extract(week from current_date)::int)) as now_pos)
  select coalesce(jsonb_agg(jsonb_build_object('week', t.week, 'topic', t.topic, 'note', t.note)
                            order by lektionskollen.school_year_pos(t.week)), '[]'::jsonb)
    from lektionskollen.term_plan t, w
   where t.school_id = lektionskollen.current_school()
     and t.subject = lektionskollen.canon_subject(p_subject) and t.year_group = lektionskollen.canon_year(p_year)
     and lektionskollen.school_year_pos(t.week) <  w.now_pos
     and lektionskollen.school_year_pos(t.week) >= w.now_pos - greatest(1, least(10, coalesce(p_back, 3)));
$function$;

CREATE OR REPLACE FUNCTION public.lk_update_plan_body(p_id uuid, p_body jsonb, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare r lektionskollen.plans;
begin
  if p_body is null or jsonb_typeof(p_body) <> 'object' or length(p_body::text) > 200000 then
    return jsonb_build_object('ok', false, 'error', 'bad_body');
  end if;
  update lektionskollen.plans
     set body_prev = body, body = p_body, body_changed_at = now(), body_alt = null, language_alt = null,
         body_change_note = left(nullif(btrim(coalesce(p_note, '')), ''), 300),
         check_result = null, checked_at = null
   where id = p_id and school_id = lektionskollen.current_school()
   returning * into r;
  if r.id is null then return jsonb_build_object('ok', false, 'error', 'not_ours'); end if;
  return jsonb_build_object('ok', true,
    'check', public.lk_check_plan(r.body, r.minutes, r.language),
    'approval_rank', lektionskollen.live_rank(r.approved, r.approved_kind, r.approved_qualified, r.approved_sha, r.body));
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_uses()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'plan_id', u.plan_id, 'group_name', u.group_name,
           'used_on', u.used_on, 'substitute', u.substitute,
           'run_token', u.run_token, 'lesson_time', u.lesson_time) order by u.used_on desc, u.created_at desc), '[]'::jsonb)
    from lektionskollen.plan_uses u
   where u.school_id = lektionskollen.current_school();
$function$;

CREATE OR REPLACE FUNCTION public.lk_validate_board(p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  probs jsonb := '[]'::jsonb;
  tk jsonb; mt jsonb;
  ans text; board text; j int := 0;
begin
  if p_body is null or jsonb_typeof(p_body) <> 'object' then return probs; end if;
  board := coalesce(p_body ->> 'board', '');

  if jsonb_typeof(p_body -> 'tasks') = 'array' then
    for tk in select * from jsonb_array_elements(p_body -> 'tasks') loop
      j := j + 1;
      ans := btrim(coalesce(tk ->> 'a', ''));
      continue when length(ans) < 3;

      if board <> '' and position(ans in board) > 0 then
        probs := probs || jsonb_build_object(
          'level', 'blocker', 'code', 'answer_on_board', 'where', 'board',
          'detail', 'The answer to task ' || j ||
                    ' is printed on the board the class sees: "' || ans || '"');
      end if;

      if jsonb_typeof(p_body -> 'materials') = 'array' then
        for mt in select * from jsonb_array_elements(p_body -> 'materials') loop
          if position(ans in coalesce(mt ->> 'body', '')) > 0 then
            probs := probs || jsonb_build_object(
              'level', 'blocker', 'code', 'answer_on_handout',
              'where', 'handout: ' || coalesce(mt ->> 'h', '?'),
              'detail', 'The answer to task ' || j ||
                        ' is printed on a pupil handout: "' || ans || '"');
          end if;
        end loop;
      end if;
    end loop;
  end if;

  return probs;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_validate_full(p_body jsonb, p_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with s as (select public.lk_validate_plan(p_body, p_minutes) v),
       t as (select public.lk_validate_teaching(p_body) v),
       r as (select public.lk_validate_tiers(p_body) v),
       p as (select ((select v -> 'problems' from s) || (select v from t) || (select v from r)) probs)
  select jsonb_build_object(
    'ok', not exists (select 1 from jsonb_array_elements(probs) x where x ->> 'level' = 'blocker'),
    'blockers', (select count(*) from jsonb_array_elements(probs) x where x ->> 'level' = 'blocker'),
    'warnings', (select count(*) from jsonb_array_elements(probs) x where x ->> 'level' = 'warn'),
    'problems', probs) from p;
$function$;

CREATE OR REPLACE FUNCTION public.lk_validate_language(p_body jsonb, p_language text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  txt text; sv int := 0; en int := 0; w text; want text;
  sv_words constant text[] := array['och','är','inte','för','att','på','med','den','det','som','ska','här'];
  en_words constant text[] := array['and','the','is','not','for','to','on','with','they','that','will','here'];
begin
  want := case when lower(coalesce(p_language, 'sv')) like 'en%' then 'en' else 'sv' end;
  txt := lower(regexp_replace(coalesce(p_body::text, ''), '[^[:alpha:]]+', ' ', 'g'));

  foreach w in array sv_words loop
    sv := sv + regexp_count(txt, '\m' || w || '\M');
  end loop;
  foreach w in array en_words loop
    en := en + regexp_count(txt, '\m' || w || '\M');
  end loop;

  if want = 'sv' and en > sv * 2 and en >= 10 then
    return jsonb_build_array(jsonb_build_object(
      'level', 'warn', 'code', 'language_mismatch', 'where', 'plan',
      'detail', 'Asked for Swedish but the text reads as English (' ||
                en || ' English markers against ' || sv || ' Swedish).'));
  end if;
  if want = 'en' and sv > en * 2 and sv >= 10 then
    return jsonb_build_array(jsonb_build_object(
      'level', 'warn', 'code', 'language_mismatch', 'where', 'plan',
      'detail', 'Asked for English but the text reads as Swedish (' ||
                sv || ' Swedish markers against ' || en || ' English).'));
  end if;
  return '[]'::jsonb;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_validate_plan(p_body jsonb, p_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  probs jsonb := '[]'::jsonb;
  ph jsonb; ck jsonb; tk jsonb; mt jsonb;
  i int := 0; j int;
  mins_total int := 0; a int; b int; t text;
  add_blocker constant text := 'blocker';
  add_warn    constant text := 'warn';
begin
  if p_body is null or jsonb_typeof(p_body) <> 'object' then
    return jsonb_build_object('ok', false, 'blockers', 1, 'warnings', 0,
      'problems', jsonb_build_array(jsonb_build_object(
        'level', add_blocker, 'code', 'no_body', 'where', 'plan',
        'detail', 'The plan has no content.')));
  end if;

  if coalesce(btrim(p_body ->> 'summary'), '') = '' then
    probs := probs || jsonb_build_object('level', add_blocker, 'code', 'no_summary',
      'where', 'overview', 'detail', 'No overview — the substitute has nothing to read first.');
  end if;
  if coalesce(btrim(p_body ->> 'goal'), '') = '' then
    probs := probs || jsonb_build_object('level', add_blocker, 'code', 'no_goal',
      'where', 'goal', 'detail', 'No learning goal.');
  end if;
  if coalesce(btrim(p_body ->> 'board'), '') = '' then
    probs := probs || jsonb_build_object('level', add_blocker, 'code', 'no_board',
      'where', 'board', 'detail', 'Nothing to write on the board before the lesson.');
  elsif length(p_body ->> 'board') > 600 then
    probs := probs || jsonb_build_object('level', add_warn, 'code', 'board_long',
      'where', 'board', 'detail', 'The board text is long — nobody writes that much before a bell.');
  end if;
  if coalesce(jsonb_typeof(p_body -> 'first90'), 'none') <> 'array'
     or jsonb_array_length(p_body -> 'first90') = 0 then
    probs := probs || jsonb_build_object('level', add_warn, 'code', 'no_first90',
      'where', 'first90', 'detail', 'No opening steps for the first ninety seconds.');
  end if;
  if coalesce(btrim(p_body #>> '{equipment,need}'), '') = '' then
    probs := probs || jsonb_build_object('level', add_warn, 'code', 'no_equipment',
      'where', 'equipment', 'detail', 'Does not say what the substitute needs.');
  end if;

  if coalesce(jsonb_typeof(p_body -> 'phases'), 'none') <> 'array'
     or jsonb_array_length(p_body -> 'phases') = 0 then
    probs := probs || jsonb_build_object('level', add_blocker, 'code', 'no_phases',
      'where', 'phases', 'detail', 'The lesson has no phases.');
  else
    for ph in select * from jsonb_array_elements(p_body -> 'phases') loop
      i := i + 1;
      if coalesce(btrim(ph ->> 'n'), '') = '' then
        probs := probs || jsonb_build_object('level', add_warn, 'code', 'phase_unnamed',
          'where', 'phase ' || i, 'detail', 'This phase has no name.');
      end if;
      if coalesce(btrim(ph ->> 'pupils'), '') = '' then
        probs := probs || jsonb_build_object('level', add_warn, 'code', 'phase_no_pupils',
          'where', 'phase ' || i, 'detail', 'Does not say what the pupils do.');
      end if;
      j := 0;
      if jsonb_typeof(ph -> 'checks') = 'array' then
        for ck in select * from jsonb_array_elements(ph -> 'checks') loop
          j := j + 1;
          if public.lk_is_pointer(ck ->> 'a') then
            probs := probs || jsonb_build_object('level', add_blocker, 'code', 'check_no_answer',
              'where', 'phase ' || i || ', check ' || j,
              'detail', 'The check question has no answer — it points somewhere else: "' ||
                        coalesce(ck ->> 'a', '') || '"');
          end if;
        end loop;
      end if;
      t := ph ->> 't';
      if t ~ '^\s*\d{1,2}:\d{2}\s*[–-]\s*\d{1,2}:\d{2}\s*$' then
        a := (split_part(btrim(split_part(replace(t, '–', '-'), '-', 1)), ':', 1))::int * 60
           + (split_part(btrim(split_part(replace(t, '–', '-'), '-', 1)), ':', 2))::int;
        b := (split_part(btrim(split_part(replace(t, '–', '-'), '-', 2)), ':', 1))::int * 60
           + (split_part(btrim(split_part(replace(t, '–', '-'), '-', 2)), ':', 2))::int;
        if b > a then mins_total := mins_total + (b - a); end if;
      end if;
    end loop;

    if p_minutes is not null and mins_total > 0 and abs(mins_total - p_minutes) > 5 then
      probs := probs || jsonb_build_object('level', add_warn, 'code', 'time_mismatch',
        'where', 'phases',
        'detail', 'The phases add up to ' || mins_total || ' minutes but the lesson is ' ||
                  p_minutes || '.');
    end if;
  end if;

  if coalesce(jsonb_typeof(p_body -> 'tasks'), 'none') <> 'array'
     or jsonb_array_length(p_body -> 'tasks') = 0 then
    probs := probs || jsonb_build_object('level', add_blocker, 'code', 'no_tasks',
      'where', 'tasks', 'detail', 'No tasks for the pupils.');
  else
    j := 0;
    for tk in select * from jsonb_array_elements(p_body -> 'tasks') loop
      j := j + 1;
      if coalesce(btrim(tk ->> 'q'), '') = '' then
        probs := probs || jsonb_build_object('level', add_blocker, 'code', 'task_empty',
          'where', 'task ' || j, 'detail', 'Empty task.');
      end if;
      if public.lk_is_pointer(tk ->> 'a') then
        probs := probs || jsonb_build_object('level', add_blocker, 'code', 'task_no_answer',
          'where', 'task ' || j,
          'detail', 'No answer for this task — it points somewhere else: "' ||
                    coalesce(tk ->> 'a', '') || '"');
      end if;
    end loop;
  end if;

  if coalesce(btrim(p_body #>> '{exit,q}'), '') = '' then
    probs := probs || jsonb_build_object('level', add_warn, 'code', 'no_exit',
      'where', 'exit', 'detail', 'No exit ticket.');
  elsif public.lk_is_pointer(p_body #>> '{exit,a}') then
    probs := probs || jsonb_build_object('level', add_blocker, 'code', 'exit_no_answer',
      'where', 'exit', 'detail', 'The exit ticket has no answer.');
  end if;

  if jsonb_typeof(p_body -> 'materials') = 'array' then
    j := 0;
    for mt in select * from jsonb_array_elements(p_body -> 'materials') loop
      j := j + 1;
      if coalesce(btrim(mt ->> 'body'), '') = '' then
        probs := probs || jsonb_build_object('level', add_warn, 'code', 'material_empty',
          'where', 'handout ' || j, 'detail', 'A handout is named but has no content.');
      end if;
    end loop;
  end if;

  foreach t in array array['stuck', 'ahead', 'wrong'] loop
    if coalesce(btrim(p_body ->> t), '') = '' then
      probs := probs || jsonb_build_object('level', add_warn, 'code', 'no_' || t,
        'where', t, 'detail', 'Missing: what to do if ' ||
          case t when 'stuck' then 'a pupil is stuck'
                 when 'ahead' then 'a pupil finishes early'
                 else 'the lesson goes wrong' end || '.');
    end if;
  end loop;

  return jsonb_build_object(
    'ok', not exists (select 1 from jsonb_array_elements(probs) x where x ->> 'level' = 'blocker'),
    'blockers', (select count(*) from jsonb_array_elements(probs) x where x ->> 'level' = 'blocker'),
    'warnings', (select count(*) from jsonb_array_elements(probs) x where x ->> 'level' = 'warn'),
    'problems', probs);
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_validate_quality(p_body jsonb, p_language text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  probs jsonb := '[]'::jsonb;
  qs    jsonb := '[]'::jsonb;      -- [{w, q, kind}]
  x jsonb; ph jsonb; ck jsonb; i int; j int;
  q text; w text; seen text[] := '{}'; norm text; has_passage boolean := false;
  starters text[] := '{}';
  ref_always constant text :=
    '\m(texten|artikeln|novellen|dikten|diagrammet|tabellen|grafen|bilden|sidan|videon|filmen|arbetsbladet) (du|ni) (fick|har fått|får)\M'
    || '|\m(you were given|you got|you have been given)\M'
    || '|\mthe (text|article|page|passage|poem|chart|graph|table|worksheet) (you|we) ';
  ref_needs_text constant text :=
    '\m(i|ur|från) (texten|artikeln|novellen|dikten|diagrammet|tabellen)\M'
    || '|\m(in|from|of) the (text|article|passage|story|poem|chart|graph|table|picture|video)\M'
    || '|\m(summarise|summarize) the (article|text)\M'
    || '|\mwhat is the article about\M';
  quoted constant text := '[”“"‘’«»]';
begin
  if p_body is null or jsonb_typeof(p_body) <> 'object' then return probs; end if;

  -- Every question a pupil is asked, with where it lives.
  if jsonb_typeof(p_body -> 'tasks') = 'array' then
    i := 0;
    for x in select * from jsonb_array_elements(p_body -> 'tasks') loop
      i := i + 1; qs := qs || jsonb_build_object('w', 'task ' || i, 'q', coalesce(x ->> 'q', ''), 'kind', 'task');
    end loop;
  end if;
  if jsonb_typeof(p_body -> 'phases') = 'array' then
    i := 0;
    for ph in select * from jsonb_array_elements(p_body -> 'phases') loop
      i := i + 1; j := 0;
      if jsonb_typeof(ph -> 'checks') = 'array' then
        for ck in select * from jsonb_array_elements(ph -> 'checks') loop
          j := j + 1;
          qs := qs || jsonb_build_object('w', 'phase ' || i || ', check ' || j,
                                         'q', coalesce(ck ->> 'q', ''),
                                         'kind', case when i = 1 then 'starter' else 'check' end);
        end loop;
      end if;
    end loop;
  end if;
  if coalesce(p_body #>> '{model,p}', '') <> '' then
    qs := qs || jsonb_build_object('w', 'worked example', 'q', p_body #>> '{model,p}', 'kind', 'model'); end if;
  if coalesce(p_body #>> '{model,tq}', '') <> '' then
    qs := qs || jsonb_build_object('w', 'one together', 'q', p_body #>> '{model,tq}', 'kind', 'model'); end if;
  if coalesce(p_body #>> '{exit,q}', '') <> '' then
    qs := qs || jsonb_build_object('w', 'exit ticket', 'q', p_body #>> '{exit,q}', 'kind', 'exit'); end if;

  -- A question long enough to carry a passage means the text IS in the plan.
  for x in select * from jsonb_array_elements(qs) loop
    if length(x ->> 'q') > 220 then has_passage := true; end if;
  end loop;

  for x in select * from jsonb_array_elements(qs) loop
    q := x ->> 'q'; w := x ->> 'w';

    if q ~* ref_always or (not has_passage and q ~* ref_needs_text) then
      probs := probs || jsonb_build_object('level', 'blocker', 'code', 'phantom_reference', 'where', w,
        'detail', 'Refers to a text, page or picture that is not in the plan: "' || left(q, 90) ||
                  '". A substitute cannot run this - write the text out in the question.');
    end if;

    -- A sentence being discussed has to be in quote marks, or the question
    -- reads as one run-on sentence.
    if q !~ quoted and (
         q ~ '^(Är|Is) [^?]*\m(en åsikt|ett faktum|an opinion|a fact|ett påstående|a claim)\M'
      or q ~ '^(Gör om|Turn|Byt ut|Replace|Ge ett motargument mot|Give a counter-argument to) [A-ZÅÄÖa-zåäö]' and q !~ ':') then
      probs := probs || jsonb_build_object('level', 'blocker', 'code', 'unquoted_sentence', 'where', w,
        'detail', 'A quoted sentence has no quote marks, so the question is hard to read: "' || left(q, 90) || '"');
    end if;

    norm := lower(regexp_replace(q, '[^[:alnum:]]+', '', 'g'));
    if norm <> '' and (x ->> 'kind') = 'task' then
      if norm = any(seen) then
        probs := probs || jsonb_build_object('level', 'warn', 'code', 'duplicate_question', 'where', w,
          'detail', 'The same question is asked twice: "' || left(q, 90) || '"');
      end if;
      seen := seen || norm;
    end if;
    if (x ->> 'kind') = 'starter' then starters := starters || norm; end if;
  end loop;

  -- An exit ticket that only repeats a starter question tests nothing from
  -- the lesson itself.
  norm := lower(regexp_replace(coalesce(p_body #>> '{exit,q}', ''), '[^[:alnum:]]+', '', 'g'));
  if norm <> '' and norm = any(starters) then
    probs := probs || jsonb_build_object('level', 'warn', 'code', 'exit_repeats_starter', 'where', 'exit ticket',
      'detail', 'The exit question is one of the starter questions, so it tests nothing from this lesson.');
  end if;

  return probs;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_validate_teaching(p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  probs jsonb := '[]'::jsonb;
  st jsonb; mc jsonb; q jsonb; ph jsonb;
  i int := 0;
  exit_q text; task1 text; says text;
begin
  if p_body is null or jsonb_typeof(p_body) <> 'object' then return probs; end if;

  -- Rosenshine 4. A lesson with practice but no model asks a substitute who
  -- may not know the subject to invent the explanation on the spot.
  if p_body -> 'model' is null or jsonb_typeof(p_body -> 'model') <> 'object' then
    probs := probs || jsonb_build_object('level','warn','code','no_model','where','model',
      'detail','No worked example. The substitute has nothing to model before pupils practise.');
  else
    if public.lk_is_pointer(p_body #>> '{model,a}') then
      probs := probs || jsonb_build_object('level','blocker','code','model_no_answer','where','model',
        'detail','The worked example has no answer.');
    end if;
    if jsonb_typeof(p_body #> '{model,st}') <> 'array'
       or jsonb_array_length(p_body #> '{model,st}') < 2 then
      probs := probs || jsonb_build_object('level','blocker','code','model_no_steps','where','model',
        'detail','The worked example is not worked — it needs at least two steps.');
    else
      for st in select * from jsonb_array_elements(p_body #> '{model,st}') loop
        i := i + 1;
        if coalesce(btrim(st ->> 'b'), '') = '' and coalesce(btrim(st ->> 's'), '') = '' then
          probs := probs || jsonb_build_object('level','blocker','code','model_step_empty',
            'where','model, step ' || i, 'detail','This step says neither what to write nor what to say.');
        end if;
      end loop;
    end if;
    if coalesce(btrim(p_body #>> '{model,tq}'), '') <> ''
       and public.lk_is_pointer(p_body #>> '{model,ta}') then
      probs := probs || jsonb_build_object('level','blocker','code','together_no_answer','where','model',
        'detail','The "one together" question has no answer.');
    end if;
  end if;

  -- Rosenshine 1. Recall must be about what came BEFORE. The audit found the
  -- opening question identical to the exit ticket, which asks pupils to do the
  -- thing the lesson has not taught yet.
  exit_q := btrim(coalesce(p_body #>> '{exit,q}', ''));
  task1  := btrim(coalesce(p_body #>> '{tasks,0,q}', ''));

  if p_body -> 'recall' is null then
    probs := probs || jsonb_build_object('level','warn','code','no_recall','where','recall',
      'detail','No recap of prior learning to open the lesson with.');
  else
    i := 0;
    for q in select * from jsonb_array_elements(coalesce(p_body #> '{recall,qs}', '[]'::jsonb)) loop
      i := i + 1;
      if public.lk_is_pointer(q ->> 'a') then
        probs := probs || jsonb_build_object('level','blocker','code','recall_no_answer',
          'where','recall, question ' || i, 'detail','This recap question has no answer.');
      end if;
      if exit_q <> '' and btrim(q ->> 'q') = exit_q then
        probs := probs || jsonb_build_object('level','blocker','code','recall_is_exit',
          'where','recall, question ' || i,
          'detail','The recap asks the same question as the exit ticket, so the lesson opens by asking pupils to do what it has not taught yet.');
      end if;
    end loop;
  end if;

  -- The exit ticket is meant to measure the lesson, not repeat its first task.
  if exit_q <> '' and task1 <> '' and exit_q = task1 then
    probs := probs || jsonb_build_object('level','blocker','code','exit_is_task','where','exit',
      'detail','The exit ticket is identical to task 1, so it measures nothing new.');
  end if;

  -- EEF: the wrong answer pupils actually give, and the sentence that fixes it.
  if jsonb_typeof(p_body -> 'misconceptions') <> 'array'
     or jsonb_array_length(p_body -> 'misconceptions') = 0 then
    probs := probs || jsonb_build_object('level','warn','code','no_misconceptions','where','misconceptions',
      'detail','No common misconception listed, so the substitute cannot tell a normal wrong answer from a worrying one.');
  else
    i := 0;
    for mc in select * from jsonb_array_elements(p_body -> 'misconceptions') loop
      i := i + 1;
      if coalesce(btrim(mc ->> 's'), '') = '' then
        probs := probs || jsonb_build_object('level','blocker','code','misconception_no_fix',
          'where','misconception ' || i, 'detail','This names a wrong answer but not what to say about it.');
      end if;
    end loop;
  end if;

  -- The fault that started all of this: the plan tells the substitute to produce
  -- something that is not in the plan.
  says := '';
  for ph in select * from jsonb_array_elements(coalesce(p_body -> 'phases', '[]'::jsonb)) loop
    says := says || ' ' || coalesce(ph ->> 'say', '');
  end loop;
  if says ~* '(visar ett exempel|jag räknar ett exempel|show you an example|work through one example|I.ll show)'
     and p_body -> 'model' is null then
    probs := probs || jsonb_build_object('level','blocker','code','promised_example_missing','where','script',
      'detail','The script tells the substitute to show an example, but the plan contains no worked example.');
  end if;

  -- Where the handouts physically are. The commonest real-world sub-plan failure.
  if coalesce(btrim(p_body #>> '{equipment,where}'), '') = '' then
    probs := probs || jsonb_build_object('level','warn','code','no_where','where','equipment',
      'detail','Does not say where the materials actually are in the room.');
  end if;

  return probs;
end; $function$;

CREATE OR REPLACE FUNCTION public.lk_validate_tiers(p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  probs jsonb := '[]'::jsonb;
  x jsonb; i int := 0; seen text[] := '{}'; missing text[];
begin
  if jsonb_typeof(p_body -> 'tasks') <> 'array'
     or jsonb_array_length(p_body -> 'tasks') = 0 then
    return probs;   -- lk_validate_plan already blocks a plan with no tasks
  end if;

  for x in select * from jsonb_array_elements(p_body -> 'tasks') loop
    i := i + 1;
    if coalesce(x ->> 'tier', '') not in ('support', 'core', 'extension') then
      probs := probs || jsonb_build_object('level', 'blocker', 'code', 'task_no_tier',
        'where', 'task ' || i,
        'detail', 'This task is not marked support, core or extension, so the substitute cannot tell who it is for.');
    else
      seen := seen || (x ->> 'tier');
    end if;
  end loop;

  missing := array(select t from unnest(array['support','core','extension']) t
                    where not (t = any (seen)));
  if array_length(missing, 1) > 0 then
    probs := probs || jsonb_build_object('level', 'blocker', 'code', 'tier_missing',
      'where', 'tasks',
      'detail', 'No tasks at the ' || array_to_string(missing, ' or ') ||
                ' level, so a pupil who needs one has nothing to do.');
  end if;

  return probs;
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.apply_threshold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  update lektionskollen.plans p
     set shared = lektionskollen.should_share(new.plan_id)
   where p.id = new.plan_id and p.approved;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.approval_label(p_kind text, p_qualified boolean)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_kind = 'teacher' and coalesce(p_qualified, false)
              then 'qualified' else p_kind end;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.assist_quota_left(p_plan uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select case when x.cap = -1 then 999999 else x.cap - x.used end
    from (select coalesce((select s.assist_cap from lektionskollen.school_settings s
                             join lektionskollen.plans p on p.school_id = s.school_id
                            where p.id = p_plan), 20) as cap,
                 (select count(*)::int from lektionskollen.plan_extras
                   where plan_id = p_plan and created_by_kind = 'vikarie'
                     and created_at > now() - interval '1 day') as used) x;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.auto_review_all()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare r record;
begin
  for r in select id from lektionskollen.plan_extras where not reviewed loop
    perform lektionskollen.auto_review_extra(r.id);
  end loop;
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.auto_review_extra(p_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare e lektionskollen.plan_extras;
begin
  select * into e from lektionskollen.plan_extras where id = p_id for update;
  if e.id is null or e.reviewed then return; end if;
  if e.sub_verdict = 'down' then
    update lektionskollen.plan_extras set reviewed = true, kept = false, reviewed_at = now(), auto_reason = 'sub_down' where id = p_id;
  elsif not lektionskollen.extra_ok(e.body) then
    update lektionskollen.plan_extras set auto_reason = 'check_failed' where id = p_id;
  elsif e.sub_verdict = 'up' or e.created_at < now() - interval '1 day' then
    update lektionskollen.plan_extras set reviewed = true, kept = true, reviewed_at = now(),
           auto_reason = case when e.sub_verdict = 'up' then 'sub_up' else 'no_complaint' end where id = p_id;
  end if;
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.canon_subject(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case lower(btrim(coalesce(p, '')))
    when 'idrott'            then 'Idrott och hälsa'
    when 'idrott & hälsa'    then 'Idrott och hälsa'
    when 'hemkunskap'        then 'Hem- och konsumentkunskap'
    when 'hkk'               then 'Hem- och konsumentkunskap'
    when 'sva'               then 'Svenska som andraspråk'
    when 'svenska som andra språk' then 'Svenska som andraspråk'
    when 'religion'          then 'Religionskunskap'
    when 'sv'                then 'Svenska'
    when 'ma'                then 'Matematik'
    when 'en'                then 'Engelska'
    else btrim(coalesce(p, ''))
  end;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.canon_year(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when lower(btrim(coalesce(p, ''))) in ('f', 'fsk', 'f-klass', 'förskoleklass', 'forskoleklass') then 'F'
    when btrim(coalesce(p, '')) ~* '^(åk|ak|årskurs)\s*\d+$'
      then 'Åk ' || regexp_replace(btrim(p), '\D', '', 'g')
    else btrim(coalesce(p, ''))
  end;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.current_school()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(lektionskollen.my_school(), lektionskollen.demo_school());
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.demo_school()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select id from lektionskollen.schools where fvk_ref = 'TESTBERGA' limit 1;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.demote_on_repeat_assist()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
begin
  if new.created_by_kind <> 'vikarie' or new.kind <> 'explain' then return new; end if;
  update lektionskollen.plans set shared = lektionskollen.should_share(new.plan_id)
   where id = new.plan_id;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.extra_ok(p_body jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select p_body is not null and jsonb_typeof(p_body) = 'object'
     and (coalesce(jsonb_array_length(case when jsonb_typeof(p_body -> 'lines') = 'array' then p_body -> 'lines' end), 0) > 0
          or coalesce(btrim(p_body ->> 'board'), '') <> ''
          or coalesce(jsonb_array_length(case when jsonb_typeof(p_body -> 'tasks') = 'array' then p_body -> 'tasks' end), 0) > 0)
     and not exists (
       select 1 from jsonb_array_elements(case when jsonb_typeof(p_body -> 'tasks') = 'array' then p_body -> 'tasks' else '[]'::jsonb end) t
        where coalesce(btrim(t ->> 'q'), '') = '' or public.lk_is_pointer(t ->> 'a'));
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.is_member(sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select exists (select 1 from lektionskollen.members m where m.school_id = sid and m.user_id = auth.uid());
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.live_rank(p_approved boolean, p_kind text, p_qualified boolean, p_sha text, p_body jsonb)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when not coalesce(p_approved, false) then 0
    when p_sha is not null and p_sha <> lektionskollen.plan_sha(p_body) then 0
    when p_kind = 'coordinator' then 1
    when p_kind = 'teacher' then case when coalesce(p_qualified, false) then 3 else 2 end
    else 0 end;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.my_school()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select school_id from lektionskollen.members where user_id = auth.uid() limit 1;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.plan_sha(p_body jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select md5(coalesce(p_body::text, ''));
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.school_year_pos(p_week integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_week >= 32 then p_week - 32 else p_week + 21 end;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.share_after_approve()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare want boolean;
begin
  want := coalesce(lektionskollen.should_share(new.id), false);
  if want is distinct from new.shared then
    update lektionskollen.plans set shared = want where id = new.id;
  end if;
  return null;
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.share_allowed(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce(p.share_allowed,
                  case when p.origin = 'ai' then coalesce(ss.share_ai, true) else false end)
    from lektionskollen.plans p
    left join lektionskollen.school_settings ss on ss.school_id = p.school_id
   where p.id = p_id;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.should_share(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
  select coalesce((select approved and (approved_sha is null or approved_sha = lektionskollen.plan_sha(body))
                     from lektionskollen.plans where id = p_id), false)
     and coalesce(lektionskollen.share_allowed(p_id), false)
     and not coalesce((s->>'burnt')::boolean, false)
     and not (coalesce((s->>'n')::int, 0) >= 3 and coalesce((s->>'score')::numeric, 1) < 0.40)
     and coalesce((f->>'wrong')::int, 0) = 0
     and coalesce((v->>'ok')::boolean, true)
    from (select public.lk_plan_standing(p_id) as s,
                 public.lk_teacher_flags(p_id) as f,
                 (select public.lk_validate_plan(body, minutes)
                    from lektionskollen.plans where id = p_id) as v) q;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_assemble(c jsonb, meta jsonb, lang text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with k as (select lektionskollen.sim_marks((meta ->> 'm')::int) as marks),
       w as (select case when lang = 'sv' then
               jsonb_build_object(
                 'recall',  'Repetition', 'model', 'Genomgång på tavlan',
                 'together','Vi gör ett tillsammans', 'indep', 'Eget arbete', 'exit', 'Exit-fråga',
                 'summary', 'Eleverna repeterar det de behöver, ser ett exempel på tavlan, gör ett tillsammans med dig och arbetar sedan själva. Du behöver inga förkunskaper — varje steg står utskrivet och alla svar finns med.',
                 'sayRecall','"Innan vi börjar — två frågor om sådant ni redan kan. Inga händer upp, jag frågar."',
                 'sayModel', '"Titta på tavlan. Jag går igenom ett exempel och säger varje steg högt. Skriv av."',
                 'sayTog',   '"Nu gör vi ett tillsammans. Jag skriver, ni säger vad jag ska göra."',
                 'sayIndep', '"Nu arbetar ni själva. Jag går runt. Räck upp handen om ni fastnar."',
                 'sayExit',  '"Sista fem minuterna. Skriv svaret på en lapp med ert namn och lämna den till mig på vägen ut."',
                 'pupRecall','Svarar när du pekar på dem. Skriv svaren på tavlan.',
                 'pupModel', 'Tittar och skriver av exemplet steg för steg.',
                 'pupTog',   'Säger nästa steg högt. En elev får komma fram och skriva.',
                 'pupIndep', 'Arbetar med uppgifterna i boken eller på arbetsbladet.',
                 'pupExit',  'Skriver svaret på en lapp och lämnar in den.',
                 'expRecall','Alla kommer inte ihåg. Det är meningen — därför repeterar vi.',
                 'expModel', 'Tyst i klassrummet här. Om det blir prat, stanna och vänta.',
                 'expTog',   'Två eller tre räcker upp handen. Fråga någon som inte gjorde det.',
                 'expIndep', 'De snabbaste är klara efter halva tiden — se "klara tidigt".',
                 'expExit',  'Räkna lapparna mot närvaron. Saknas någon, fråga vem.',
                 'need',     'Whiteboard och penna. Inget annat krävs.',
                 'fallback', 'Om projektorn är trasig spelar det ingen roll — hela lektionen går på tavlan.',
                 'stuck',    'Gå tillbaka till exemplet på tavlan och gör uppgift 1 med dem, steg för steg.',
                 'ahead',    'Be dem skriva en egen uppgift av samma typ, med facit, till en kompis.',
                 'wrong',    'Blir det stökigt: tyst skrivande i fem minuter, samla in, avsluta med exit-frågan.',
                 'sheet',    'Arbetsblad', 'copier', '(Skriv uppgifterna på tavlan om kopiatorn inte fungerar.)',
                 'worked',   'Exempel', 'handover', 'Vi hann ')
             else
               jsonb_build_object(
                 'recall',  'Recap', 'model', 'Worked example on the board',
                 'together','One together', 'indep', 'Independent work', 'exit', 'Exit question',
                 'summary', 'Pupils recap what they need, watch a worked example on the board, do one with you, then work on their own. You need no prior knowledge — every step is written out and every answer is included.',
                 'sayRecall','"Before we start — two questions about things you already know. No hands up, I''ll pick."',
                 'sayModel', '"Look at the board. I''ll work through one example and say every step out loud. Copy it down."',
                 'sayTog',   '"Now we do one together. I write, you tell me what to do."',
                 'sayIndep', '"Now work on your own. I''ll come round. Hand up if you get stuck."',
                 'sayExit',  '"Last five minutes. Write the answer on a slip with your name and hand it to me on the way out."',
                 'pupRecall','Answer when you point at them. Write the answers on the board.',
                 'pupModel', 'Watch and copy the example down step by step.',
                 'pupTog',   'Call out the next step. One pupil comes up and writes.',
                 'pupIndep', 'Work through the tasks in the book or on the worksheet.',
                 'pupExit',  'Write the answer on a slip and hand it in.',
                 'expRecall','Not everyone will remember. That is the point — that is why we recap.',
                 'expModel', 'The room should be quiet here. If it is not, stop and wait.',
                 'expTog',   'Two or three hands will go up. Ask someone whose did not.',
                 'expIndep', 'The quickest finish halfway through — see "finished early".',
                 'expExit',  'Count the slips against the register. If one is missing, ask who.',
                 'need',     'Whiteboard and pen. Nothing else is required.',
                 'fallback', 'If the projector is broken it makes no difference — the whole lesson runs on the board.',
                 'stuck',    'Go back to the example on the board and do task 1 with them, step by step.',
                 'ahead',    'Ask them to write their own task of the same kind, with the answer, for a partner.',
                 'wrong',    'If it gets noisy: five minutes of silent writing, collect it in, finish with the exit question.',
                 'sheet',    'Worksheet', 'copier', '(Write the tasks on the board if the copier is broken.)',
                 'worked',   'Worked example', 'handover', 'We got through ')
             end as w)
  select jsonb_build_object(
    'title', c ->> 'title',
    'summary', w ->> 'summary',
    'goal', c ->> 'goal',
    'curriculum', (meta ->> 'su') || ' ' || (meta ->> 'y') || ' — ' ||
                  case when lang = 'sv' then 'centralt innehåll.' else 'core content.' end,
    'readTime', '3 min',
    'board', (c ->> 'boardTitle') || chr(10) || (c ->> 'goal') || chr(10) || chr(10) || (c #>> '{model,p}'),
    'equipment', jsonb_build_object(
      'need', w ->> 'need', 'fallback', w ->> 'fallback', 'where', c ->> 'where'),
    'first90', c -> 'first90',
    'recall', c -> 'recall',
    'model', c -> 'model',
    'misconceptions', c -> 'misconceptions',
    'phases', jsonb_build_array(
      jsonb_build_object('t', lektionskollen.sim_span((select marks from k), 1),
        'n', w ->> 'recall', 'say', w ->> 'sayRecall', 'pupils', w ->> 'pupRecall',
        'expect', w ->> 'expRecall', 'board', c #>> '{recall,why}',
        'checks', c #> '{recall,qs}'),
      jsonb_build_object('t', lektionskollen.sim_span((select marks from k), 2),
        'n', w ->> 'model', 'say', w ->> 'sayModel', 'pupils', w ->> 'pupModel',
        'expect', w ->> 'expModel',
        'board', (select string_agg(s ->> 'b', chr(10) order by o)
                    from jsonb_array_elements(c #> '{model,st}') with ordinality as t(s, o)),
        'checks', jsonb_build_array(jsonb_build_object(
          'q', c #>> '{model,p}', 'a', c #>> '{model,a}'))),
      jsonb_build_object('t', lektionskollen.sim_span((select marks from k), 3),
        'n', w ->> 'together', 'say', w ->> 'sayTog', 'pupils', w ->> 'pupTog',
        'expect', w ->> 'expTog', 'board', c #>> '{model,tq}',
        'checks', jsonb_build_array(jsonb_build_object(
          'q', c #>> '{model,tq}', 'a', c #>> '{model,ta}'))),
      jsonb_build_object('t', lektionskollen.sim_span((select marks from k), 4),
        'n', w ->> 'indep', 'say', w ->> 'sayIndep', 'pupils', w ->> 'pupIndep',
        'expect', w ->> 'expIndep',
        'board', (select string_agg(o || '. ' || (x ->> 'q'), chr(10) order by o)
                    from jsonb_array_elements(c -> 'tasks') with ordinality as t(x, o)),
        'checks', jsonb_build_array()),
      jsonb_build_object('t', lektionskollen.sim_span((select marks from k), 5),
        'n', w ->> 'exit', 'say', w ->> 'sayExit', 'pupils', w ->> 'pupExit',
        'expect', w ->> 'expExit', 'board', c #>> '{exit,q}',
        'checks', jsonb_build_array(jsonb_build_object(
          'q', c #>> '{exit,q}', 'a', c #>> '{exit,a}')))),
    'materials', jsonb_build_array(
      jsonb_build_object('h', w ->> 'worked',
        'body', (c #>> '{model,p}') || chr(10) || chr(10) ||
                (select string_agg(s ->> 'b', chr(10) order by o)
                   from jsonb_array_elements(c #> '{model,st}') with ordinality as t(s, o))),
      jsonb_build_object('h', w ->> 'sheet',
        'body', (select string_agg(o || '. ' || (x ->> 'q'), chr(10) order by o)
                   from jsonb_array_elements(c -> 'tasks') with ordinality as t(x, o))
                || chr(10) || chr(10) || (w ->> 'copier'))),
    'tasks', c -> 'tasks',
    'stuck', w ->> 'stuck',
    'ahead', w ->> 'ahead',
    'wrong', w ->> 'wrong',
    'exit', c -> 'exit',
    'handover', (w ->> 'handover') || lower(c ->> 'title') || '.')
  from k, w;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_body(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select jsonb_build_object(
    'title', p ->> 't',
    'summary', 'Eleverna repeterar ' || lower(p ->> 't') || ' och arbetar sedan själva. Du behöver inga förkunskaper — allt du ska säga står utskrivet och alla svar finns med.',
    'goal', 'Jag kan ' || (p ->> 'g') || '.',
    'curriculum', (p ->> 'su') || ' ' || (p ->> 'y') || ' — centralt innehåll.',
    'readTime', '3 min',
    'board', 'Dagens mål' || chr(10) || (p ->> 'g') || chr(10) || chr(10) || (p ->> 'q'),
    'equipment', jsonb_build_object(
      'need', 'Whiteboard och penna. Inget annat krävs.',
      'fallback', 'Om projektorn är trasig spelar det ingen roll — hela lektionen går på tavlan.'),
    'first90', jsonb_build_array(
      'Stå vid dörren. Säg god morgon till varje elev som kommer in.',
      'Skriv ditt namn på tavlan innan lektionen börjar.',
      'Säg: "Jag heter [ditt namn] och jag är här idag. Vi arbetar med ' || lower(p ->> 'su') || '. Sitt där ni brukar sitta."',
      'Ta närvaron högt från listan. Det tar 60 sekunder och sätter tonen.'),
    'phases', jsonb_build_array(
      jsonb_build_object(
        't', '00:00–00:' || lpad(greatest(3, (p ->> 'm')::int / 4)::text, 2, '0'),
        'n', 'Repetition',
        'say', '"Vad minns ni om ' || lower(p ->> 't') || '? Inga händer upp — jag frågar fyra av er."',
        'pupils', 'Svarar när du pekar på dem. Skriv svaren på tavlan.',
        'expect', 'De flesta minns rubriken men inte detaljerna. Det är meningen.',
        'checks', jsonb_build_array(jsonb_build_object('q', p ->> 'q', 'a', p ->> 'a'))),
      jsonb_build_object(
        't', '00:' || lpad(greatest(3, (p ->> 'm')::int / 4)::text, 2, '0') || '–00:' || lpad((greatest(3, (p ->> 'm')::int / 4) * 2)::text, 2, '0'),
        'n', 'Genomgång på tavlan',
        'say', '"Titta på tavlan. ' || (p ->> 'g') || '. Jag visar ett exempel, sedan gör vi ett tillsammans."',
        'pupils', 'Tittar och svarar. Två elever får komma fram.',
        'expect', 'Någon frågar om det kommer på provet. Svara: det kan komma.',
        'checks', jsonb_build_array(jsonb_build_object(
          'q', 'Kan någon förklara steget med egna ord?',
          'a', 'Låt två elever svara innan du rättar. Rätt svar är det som stämmer med tavlan.'))),
      jsonb_build_object(
        't', '00:' || lpad((greatest(3, (p ->> 'm')::int / 4) * 2)::text, 2, '0') || '–00:' || (p ->> 'm'),
        'n', 'Eget arbete',
        'say', '"Nu arbetar ni själva. Jag går runt. Räck upp handen om ni fastnar."',
        'pupils', 'Arbetar i boken eller på arbetsbladet.',
        'expect', 'De snabbaste är klara efter halva tiden — se "klara tidigt".',
        'checks', jsonb_build_array())),
    'materials', jsonb_build_array(jsonb_build_object(
      'h', 'Arbetsblad',
      'body', (p ->> 'q') || chr(10) || chr(10) || '(Skriv uppgiften på tavlan om kopiatorn inte fungerar.)')),
    'tasks', jsonb_build_array(
      jsonb_build_object('q', p ->> 'q', 'a', p ->> 'a'),
      jsonb_build_object('q', 'Förklara med egna ord vad vi gjort idag.',
        'a', 'Alla svar godkänns som nämner ' || lower(p ->> 'g') || '.')),
    'stuck', 'Gör uppgift 1 gemensamt på tavlan och låt dem skriva av.',
    'ahead', 'Be dem skriva en egen uppgift av samma typ till en kompis.',
    'wrong', 'Blir det stökigt: tyst skrivande i fem minuter, samla in, avsluta med högläsning.',
    'exit', jsonb_build_object('q', p ->> 'q', 'a', p ->> 'a'),
    'handover', 'Vi hann ' || lower(p ->> 't') || '. Några blandade ihop stegen i mitten.');
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_body_en(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select jsonb_build_object(
    'title', p ->> 'te',
    'summary', 'Pupils revise ' || lower(p ->> 'te') || ', then work on their own. You need no prior knowledge — everything you say is written out and every answer is included.',
    'goal', 'I can ' || (p ->> 'ge') || '.',
    'curriculum', (p ->> 'sue') || ' ' || replace(p ->> 'y', 'Åk', 'Year') || ' — core content.',
    'readTime', '3 min',
    'board', 'Today''s goal' || chr(10) || (p ->> 'ge') || chr(10) || chr(10) || (p ->> 'qe'),
    'equipment', jsonb_build_object(
      'need', 'Whiteboard and pen. Nothing else is required.',
      'fallback', 'If the projector is broken it makes no difference — the whole lesson runs on the board.'),
    'first90', jsonb_build_array(
      'Stand at the door. Say good morning to every pupil who comes in.',
      'Write your name on the board before the lesson starts.',
      'Say: "My name is [your name] and I am here today. We are working on ' || lower(p ->> 'sue') || '. Sit where you normally sit."',
      'Take the register out loud from the list. It takes 60 seconds and sets the tone.'),
    'phases', jsonb_build_array(
      jsonb_build_object(
        't', '00:00–00:' || lpad(greatest(3, (p ->> 'm')::int / 4)::text, 2, '0'),
        'n', 'Revision',
        'say', '"What do you remember about ' || lower(p ->> 'te') || '? No hands up — I will ask four of you."',
        'pupils', 'Answer when you point at them. Write the answers on the board.',
        'expect', 'Most remember the heading but not the detail. That is the point.',
        'checks', jsonb_build_array(jsonb_build_object('q', p ->> 'qe', 'a', p ->> 'ae'))),
      jsonb_build_object(
        't', '00:' || lpad(greatest(3, (p ->> 'm')::int / 4)::text, 2, '0') || '–00:' || lpad((greatest(3, (p ->> 'm')::int / 4) * 2)::text, 2, '0'),
        'n', 'Board explanation',
        'say', '"Look at the board. ' || initcap(p ->> 'ge') || '. I will show one example, then we do one together."',
        'pupils', 'Watch and answer. Two pupils come up to the board.',
        'expect', 'Someone asks whether it is on the test. Say: it may be.',
        'checks', jsonb_build_array(jsonb_build_object(
          'q', 'Can anyone explain that step in their own words?',
          'a', 'Let two pupils answer before you correct. The right answer is the one that matches the board.'))),
      jsonb_build_object(
        't', '00:' || lpad((greatest(3, (p ->> 'm')::int / 4) * 2)::text, 2, '0') || '–00:' || (p ->> 'm'),
        'n', 'Independent work',
        'say', '"Now work on your own. I will come round. Put your hand up if you get stuck."',
        'pupils', 'Work in the book or on the worksheet.',
        'expect', 'The fastest finish halfway through — see "finished early".',
        'checks', jsonb_build_array())),
    'materials', jsonb_build_array(jsonb_build_object(
      'h', 'Worksheet',
      'body', (p ->> 'qe') || chr(10) || chr(10) || '(Write the task on the board if the copier is not working.)')),
    'tasks', jsonb_build_array(
      jsonb_build_object('q', p ->> 'qe', 'a', p ->> 'ae'),
      jsonb_build_object('q', 'Explain in your own words what we did today.',
        'a', 'Any answer that mentions ' || lower(p ->> 'ge') || ' is accepted.')),
    'stuck', 'Do task 1 together on the board and let them copy it down.',
    'ahead', 'Ask them to write a task of the same kind for a classmate.',
    'wrong', 'If it gets noisy: five minutes of silent writing, collect it in, finish by reading aloud.',
    'exit', jsonb_build_object('q', p ->> 'qe', 'a', p ->> 'ae'),
    'handover', 'We got through ' || lower(p ->> 'te') || '. A few mixed up the steps in the middle.');
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_first90(subj text, lang text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when lang = 'sv' then jsonb_build_array(
      'Stå vid dörren. Säg god morgon till varje elev som kommer in.',
      'Skriv ditt namn på tavlan innan lektionen börjar.',
      'Säg: "Jag heter [ditt namn] och jag är här idag. Vi arbetar med ' || lower(subj) || '. Sitt där ni brukar sitta."',
      'Ta närvaron högt från listan. Det tar 60 sekunder och sätter tonen.')
    else jsonb_build_array(
      'Stand at the door. Say good morning to every pupil who comes in.',
      'Write your name on the board before the lesson starts.',
      'Say: "My name is [your name] and I am here today. We are working on ' || lower(subj) || '. Sit where you normally sit."',
      'Take the register out loud from the list. It takes 60 seconds and sets the tone.')
  end;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_marks(m integer)
 RETURNS integer[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select array[0,
               round(m * 0.13)::int,
               round(m * 0.33)::int,
               round(m * 0.50)::int,
               round(m * 0.87)::int,
               m];
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_over(p_lang text, p_subj text, p_stage integer, p_safety text, p_need text, p_where text, p_handover text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  sv boolean := (p_lang = 'sv');
  young boolean := (p_stage between 0 and 3);
  babies boolean := (p_stage between 0 and 1);
  f90 jsonb; wrong text; top jsonb := '{}'::jsonb; ph jsonb := null; firstaid text;
begin
  firstaid := case when sv
    then 'Om någon skadar sig: stoppa aktiviteten, ta eleven åt sidan och kontakta skolans första hjälpen-ansvarige eller expeditionen. Hitta inte på något telefonnummer.'
    else 'If someone is hurt: stop the activity, take the pupil aside and contact the school''s first-aid person or the office. Do not make up a phone number.' end;

  if young then
    f90 := case when sv then jsonb_build_array(
        'Möt barnen vid dörren. Säg god morgon och ditt namn.',
        'Låt dem sätta sig på sina vanliga platser eller i ringen. Fråga om du är osäker var de brukar sitta.',
        'Samla gruppen: håll upp en hand och vänta tills alla är tysta och håller upp sin. Höj inte rösten.',
        'Säg: “Jag heter [ditt namn]. Idag ska vi arbeta med ' || lower(p_subj) || '.” Ta närvaron högt genom att säga varje namn.')
      else jsonb_build_array(
        'Meet the children at the door. Say good morning and your name.',
        'Let them sit in their usual places or in the circle. Ask if you are unsure where they normally sit.',
        'Gather the group: hold up one hand and wait until everyone is quiet and holding up theirs. Do not raise your voice.',
        'Say: “My name is [your name]. Today we are working on ' || lower(p_subj) || '.” Take the register out loud by saying each name.') end;
    wrong := case when sv
      then 'Blir det rörigt: samla alla i ringen eller vid tavlan, räkna eller ramsa något kort tillsammans och börja om med första uppgiften.'
      else 'If it gets messy: gather everyone in the circle or at the board, count or chant something short together and start again with the first task.' end;
    top := top || jsonb_build_object(
      'first90', f90, 'wrong', wrong,
      'summary', case when sv
        then 'Eleverna gör saker i små steg: de ser ett exempel, gör ett tillsammans med dig och prövar sedan själva. Du läser alla uppgifter högt. Varje steg står utskrivet och alla svar finns med.'
        else 'Pupils work in small steps: they see an example, do one with you and then try on their own. You read every task aloud. Every step is written out and every answer is included.' end,
      'stuck', case when sv
        then 'Gå tillbaka till exemplet på tavlan och gör första uppgiften tillsammans, steg för steg, med föremål eller händer.'
        else 'Go back to the example on the board and do the first task together, step by step, with objects or hands.' end,
      'ahead', case when sv
        then 'Be dem hitta på en egen uppgift av samma sort och ställa den till en kompis.'
        else 'Ask them to make up a task of the same kind and ask it to a friend.' end);
    ph := case when sv then jsonb_build_array(
      jsonb_build_object('say','“Innan vi börjar frågar jag två saker om sådant ni redan kan. Svara högt tillsammans.”',
        'pupils','Svarar högt tillsammans eller visar med händerna.',
        'expect','Alla svarar inte. Upprepa frågan lugnt och långsamt.'),
      jsonb_build_object('say','“Titta på tavlan. Jag visar ett exempel och säger varje steg högt. Titta och lyssna.”',
        'pupils','Tittar, lyssnar och gör efter med fingrar eller händer.',
        'expect','Det ska vara lugnt. Blir det stimmigt: håll upp en hand och vänta tills alla gör likadant.'),
      jsonb_build_object('say','“Nu gör vi ett tillsammans. Jag visar och ni säger vad jag ska göra.”',
        'pupils','Säger nästa steg högt i kör. En elev i taget får komma fram.',
        'expect','Flera barn svarar för fort eller samtidigt. Sakta ner och låt en i taget svara.'),
      jsonb_build_object('say','“Nu gör ni själva. Jag läser en uppgift i taget högt. Mitt i får ni stå upp, hoppa tre hopp och sätta er igen. Jag kommer till er.”',
        'pupils','Arbetar med föremål, händer, teckning eller samtal. Ingen behöver läsa själv.',
        'expect','De första är klara efter halva tiden. Låt dem hjälpa en kompis, se “klara tidigt”.'),
      case when babies then jsonb_build_object(
        'say','“Sista frågan. Jag frågar er en och en. Svara högt eller visa med händerna.”',
        'pupils','Svarar högt eller visar svaret med händerna.',
        'expect','Skriv upp vilka som klarade det och lämna listan till ordinarie lärare.')
      else jsonb_build_object(
        'say','“Sista frågan. Skriv svaret på en lapp med ditt namn och lämna den till mig.”',
        'pupils','Skriver ett ord eller en kort mening på en lapp.',
        'expect','Räkna lapparna mot närvaron. Saknas någon, fråga vem.') end)
    else jsonb_build_array(
      jsonb_build_object('say','“Before we start I will ask two questions about things you already know. Answer out loud together.”',
        'pupils','Answer out loud together or show with their hands.',
        'expect','Not everyone answers. Repeat the question calmly and slowly.'),
      jsonb_build_object('say','“Look at the board. I will show one example and say every step out loud. Watch and listen.”',
        'pupils','Watch, listen and copy with fingers or hands.',
        'expect','It should be calm. If it gets noisy: hold up a hand and wait until everyone does the same.'),
      jsonb_build_object('say','“Now we do one together. I show it and you tell me what to do.”',
        'pupils','Call out the next step together. One pupil at a time comes up.',
        'expect','Several children answer too fast or at once. Slow down and let one answer at a time.'),
      jsonb_build_object('say','“Now you do it yourselves. I read one task at a time out loud. Halfway through you may stand up, jump three jumps and sit down again. I will come round.”',
        'pupils','Work with objects, hands, drawing or talking. Nobody has to read on their own.',
        'expect','The first are done after half the time. Let them help a friend, see “finished early”.'),
      case when babies then jsonb_build_object(
        'say','“Last question. I ask you one by one. Answer out loud or show with your hands.”',
        'pupils','Answer out loud or show the answer with their hands.',
        'expect','Note who got it and leave the list for the class teacher.')
      else jsonb_build_object(
        'say','“Last question. Write the answer on a slip with your name and hand it to me.”',
        'pupils','Write a word or a short sentence on a slip.',
        'expect','Count the slips against the register. If one is missing, ask who.') end) end;
  end if;

  if p_safety is not null then
    f90 := coalesce(top -> 'first90', lektionskollen.sim_first90(p_subj, p_lang)) || jsonb_build_array(p_safety);
    wrong := coalesce(top ->> 'wrong', case when sv
      then 'Blir det stökigt: tyst skrivande i fem minuter, samla in, avsluta med exit-frågan.'
      else 'If it gets noisy: five minutes of silent writing, collect it in, finish with the exit question.' end)
      || ' ' || firstaid;
    top := top || jsonb_build_object('first90', f90, 'wrong', wrong);
  end if;

  if p_need is not null or p_where is not null then
    top := top || jsonb_build_object('equipment', jsonb_build_object(
      'need', coalesce(p_need, case when sv then 'Whiteboard och penna. Inget annat krävs.' else 'Whiteboard and pen. Nothing else is required.' end),
      'fallback', case when sv then 'Om något material saknas går lektionen att göra med tavlan och papper.'
                       else 'If some material is missing the lesson can run on the board and paper.' end,
      'where', coalesce(p_where, '')));
  end if;
  if p_handover is not null then top := top || jsonb_build_object('handover', p_handover); end if;

  return jsonb_strip_nulls(jsonb_build_object('top', top, 'phases', ph));
end $function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_pick(p_opts text[], p_w numeric[])
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare r numeric := random(); acc numeric := 0; i int;
begin
  for i in 1 .. array_length(p_opts, 1) loop
    acc := acc + p_w[i];
    if r <= acc then return p_opts[i]; end if;
  end loop;
  return p_opts[array_length(p_opts, 1)];
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_plan(p_key text, p_lang text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  with src as (
    select case when p_lang = 'sv' then sv else en end as c0, subject, year_group, minutes
      from lektionskollen.sim_content where key = p_key),
  built as (
    select lektionskollen.sim_assemble(
             c0 || jsonb_build_object('first90',
                     coalesce(c0 -> 'first90', lektionskollen.sim_first90(c0 ->> 'subj', p_lang))),
             jsonb_build_object('su', subject, 'y', year_group, 'm', minutes),
             p_lang) as b0,
           c0 -> 'over' as ov
      from src),
  -- A lesson may carry its own wording where the generic script does not fit
  -- the pupils or the subject: over.top replaces whole top-level fields
  -- (equipment, first90, wrong...), over.phases[i] merges into phase i.
  over as (
    select (b0 || coalesce(ov -> 'top', '{}'::jsonb))
           || jsonb_build_object('phases', (
                select jsonb_agg(ph || coalesce(ov -> 'phases' -> ((i - 1)::int), '{}'::jsonb) order by i)
                  from jsonb_array_elements(b0 -> 'phases') with ordinality as t(ph, i))) as b
      from built),
  core as (select b, lektionskollen.tasks_of(b, 'core') as c from over)
  select jsonb_set(
           jsonb_set(b, '{phases,3,board}', to_jsonb((
             select string_agg(o || '. ' || (x ->> 'q'), chr(10) order by o)
               from jsonb_array_elements(c) with ordinality as t(x, o)))),
           '{materials,1,body}', to_jsonb((
             select string_agg(o || '. ' || (x ->> 'q'), chr(10) order by o)
               from jsonb_array_elements(c) with ordinality as t(x, o))
             || chr(10) || chr(10) ||
             case when p_lang = 'sv' then '(Skriv uppgifterna på tavlan om kopiatorn inte fungerar.)'
                  else '(Write the tasks on the board if the copier is broken.)' end))
    from core;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.sim_span(marks integer[], i integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select '00:' || lpad(marks[i]::text, 2, '0') || '–00:' || lpad(marks[i + 1]::text, 2, '0');
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.tasks_of(b jsonb, p_tier text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(jsonb_agg(x order by o), '[]'::jsonb)
    from jsonb_array_elements(coalesce(b -> 'tasks', '[]'::jsonb)) with ordinality as t(x, o)
   where coalesce(x ->> 'tier', 'core') = p_tier;
$function$;

CREATE OR REPLACE FUNCTION lektionskollen.tie_to_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lektionskollen', 'pg_temp'
AS $function$
declare u record;
begin
  if new.rater_session is not null and new.rater_session like 'r\_%' then
    select id, expires_at into u from lektionskollen.plan_uses
     where run_token = substr(new.rater_session, 3) and plan_id = new.plan_id;
    if found then
      if u.expires_at is not null and u.expires_at < now() then
        raise exception 'run_expired';
      end if;
      new.use_id := u.id;
    end if;
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION lektionskollen.usage_ref(p_kind text, p_ref uuid)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_kind = 'assist' then coalesce(p_ref, '00000000-0000-0000-0000-000000000000'::uuid)
              else '00000000-0000-0000-0000-000000000000'::uuid end;
$function$;

