-- ── Triggers ──
drop trigger if exists demote_on_repeat_assist on lektionskollen.plan_extras;
CREATE TRIGGER demote_on_repeat_assist AFTER INSERT ON lektionskollen.plan_extras FOR EACH ROW EXECUTE FUNCTION lektionskollen.demote_on_repeat_assist();
drop trigger if exists ratings_tie_to_run on lektionskollen.ratings;
CREATE TRIGGER ratings_tie_to_run BEFORE INSERT ON lektionskollen.ratings FOR EACH ROW EXECUTE FUNCTION lektionskollen.tie_to_run();
drop trigger if exists section_feedback_tie_to_run on lektionskollen.section_feedback;
CREATE TRIGGER section_feedback_tie_to_run BEFORE INSERT ON lektionskollen.section_feedback FOR EACH ROW EXECUTE FUNCTION lektionskollen.tie_to_run();
drop trigger if exists share_after_approve on lektionskollen.plans;
CREATE TRIGGER share_after_approve AFTER UPDATE ON lektionskollen.plans FOR EACH ROW WHEN (((new.approved IS DISTINCT FROM old.approved) OR (new.approved_sha IS DISTINCT FROM old.approved_sha) OR (new.share_allowed IS DISTINCT FROM old.share_allowed) OR (new.body IS DISTINCT FROM old.body))) EXECUTE FUNCTION lektionskollen.share_after_approve();
drop trigger if exists trg_threshold on lektionskollen.ratings;
CREATE TRIGGER trg_threshold AFTER INSERT ON lektionskollen.ratings FOR EACH ROW EXECUTE FUNCTION lektionskollen.apply_threshold();

-- ── Nightly jobs (only where pg_cron is installed) ──
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule('lk-nightly-retention') where exists (select 1 from cron.job where jobname = 'lk-nightly-retention');
    perform cron.schedule('lk-nightly-retention', '17 3 * * *', 'select public.lk_nightly_retention()');
  end if;
end $$;
